  $$[{"id":"65e0af05-6b2d-414f-8fb8-da397b74339d","end_year":2014,"logo_url":null,"start_year":2010,"institution":"Johns Hopkins Bloomberg School of Public Health","degree_or_course":"PhD Health Systems"},{"id":"f6451a69-ec30-4971-8585-f79a2691e604","end_year":2008,"logo_url":null,"start_year":2003,"institution":"All India Institute of Medical Sciences","degree_or_course":"MBBS"}]$$::jsonb,
