-- Dr. Sunita Patel (dr-sunita-patel)
INSERT INTO profiles (id, user_id, consultant_type, handle, name, headline, location, career_level, year_founded, contracting_work_eligibility, work_types, part_time_availability, full_time_availability, availability_updated_at, photo_url, cover_image_url, detailed_bio, tiered_expertise, spoken_languages, accreditations, work_history, education_history, additional_experience, is_premium, subscription_status, approval_status, submitted_at, email, testimonial_grace_until, verification_recheck_until, is_demo) VALUES (
  'ade0f4c7-c4a6-453c-a5c4-ccf933c17362',
  NULL,
  $$Individual$$,
  $$dr-sunita-patel$$,
  $$Dr. Sunita Patel$$,
  $$Social Protection & Gender Equity Specialist | Shock-Responsive Systems | ADB & UNICEF$$,
  $$Manila, Philippines$$,
  $$senior$$,
  NULL,
  NULL,
  ARRAY[$$Remote$$, $$On-site$$]::text[],
  $${"from":null,"until":null,"status":"available_now"}$$::jsonb,
  $${"from":null,"until":null,"status":"available_now"}$$::jsonb,
  '2026-06-26T22:08:20.890452+00:00'::timestamptz,
  $$https://randomuser.me/api/portraits/women/7.jpg$$,
  $$https://picsum.photos/seed/sunita-patel/800/200$$,
  $$Dr. Sunita Patel is a leading expert on social protection systems in Southeast Asia, with a particular focus on making safety nets responsive to economic shocks, climate disasters, and health crises. Over twenty years, she has advised Asian Development Bank operations in the Philippines, Indonesia, Vietnam, and Cambodia, and has led UNICEF-supported assessments of social protection system coverage gaps. Her recent work centres on gender-transformative social protection — designing cash transfer programs that not only provide income support but actively address unpaid care work, gender-based discrimination, and women's economic agency. Dr. Patel was a key technical contributor to the Philippines' Pantawid Pamilyang Pilipino Program (4Ps) reform process and has advised Indonesia on its Social Protection Floor strategy. She holds a PhD in Development Economics from the Australian National University. She has also worked on disaster risk finance instruments that let safety nets scale up quickly after typhoons.$$,
