INSERT INTO profiles (id, user_id, consultant_type, handle, name, headline, location, career_level, year_founded, contracting_work_eligibility, work_types, part_time_availability, full_time_availability, availability_updated_at, photo_url, cover_image_url, detailed_bio, tiered_expertise, spoken_languages, accreditations, work_history, education_history, additional_experience, is_premium, subscription_status, approval_status, submitted_at, email, testimonial_grace_until, verification_recheck_until, is_demo) VALUES (
  'bcf1b059-1569-5cfd-b134-3f80c6d5f9a7',
  NULL,
  $$Individual$$,
  $$demo-grace-wanjiru-kamau$$,
  $$Grace Wanjiru Kamau$$,
  $$Climate Adaptation Policy Writer | Water & WASH Resilience | Kenya & East Africa$$,
  $$Nairobi, Kenya$$,
  $$mid_career$$,
  NULL,
  $$Kenyan citizen; contracts as an individual consultant (KRA PIN registered).$$,
  ARRAY[$$Remote$$, $$Hybrid$$]::text[],
  $${"from":null,"until":null,"status":"available_now"}$$::jsonb,
  $${"from":null,"until":null,"status":"unavailable"}$$::jsonb,
  '2026-09-28T01:52:11.647292+00:00'::timestamptz,
  $$https://randomuser.me/api/portraits/women/78.jpg$$,
  $$https://picsum.photos/seed/demo-grace-wanjiru-kamau/800/200$$,
  $$Grace Wanjiru Kamau writes and advises on climate adaptation policy in Kenya and East Africa. Over nine years she has drafted county climate change action plans, policy briefs on drought resilience and water management, and the adaptation chapters of national reports to the UNFCCC. She translates technical research on groundwater, rainfall variability and WASH services into clear options for county governments and parliamentarians, and facilitates consultations with pastoralist communities and water user associations. Grace previously worked as a research communications officer at a regional climate centre. Much of her recent writing is on drought risk management and the finance counties need to act on it.$$,
