-- Dr. Priya Nair
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('2186df77-e67c-4d53-ba03-af1c918ce732', 'ef9da174-4196-4a7d-950f-fb237c3e11ce', $$UHC Financing Roadmap, Ministry of Health, Nepal$$, $$WHO$$, (SELECT id FROM organizations WHERE name = $$World Health Organization$$), 2019, 2020, $$Lead Technical Advisor$$, $$Developed a 10-year UHC financing roadmap for the Government of Nepal, modelling three fiscal scenarios and aligning with the 15th National Development Plan. Facilitated stakeholder consultations with 18 provincial health departments.$$, $$Roadmap was endorsed by the Ministry of Health and anchored a costed 5-year UHC financing plan; two of its financing options were incorporated into the subsequent national health budget.$$, $$[{"url":"https://picsum.photos/seed/priya-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/priya-portfolio-1-img1/900/600","caption":"Costing workshop with Ministry of Health officials"},{"url":"https://picsum.photos/seed/priya-portfolio-1-img2/900/600","caption":"Field visit to a district health facility, Nepal"}]$$::jsonb, $$[{"url":"https://www.who.int/health-topics/universal-health-coverage","label":"WHO UHC resources"},{"url":"https://example.org/nepal-uhc-roadmap","label":"Roadmap overview"}]$$::jsonb, NULL, 1),
  ('7c25c5c3-1b47-42be-8177-5a1d77971934', 'ef9da174-4196-4a7d-950f-fb237c3e11ce', $$Primary Health Care Investment Case, World Bank, Bangladesh$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2013, 2015, $$Health Economist Advisor$$, $$Led the analytical work underpinning a $300M World Bank investment in Bangladesh's primary health care network, including a health facility assessment across 64 districts and costing of the Essential Services Package.$$, $$Investment case supported a US$200M+ World Bank financing decision for primary health care; the economic model became the Ministry's reference tool for facility-level resource allocation.$$, $$[{"url":"https://picsum.photos/seed/priya-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/priya-portfolio-2-img1/900/600","caption":"Primary health care facility assessment"},{"url":"https://picsum.photos/seed/priya-portfolio-2-img2/900/600","caption":"Data review session with district health teams"}]$$::jsonb, $$[{"url":"https://www.worldbank.org/en/country/bangladesh","label":"World Bank Bangladesh health"}]$$::jsonb, NULL, 2),
  ('b2b75b27-a61d-4cd2-b4e9-3ef60b368e5f', 'ef9da174-4196-4a7d-950f-fb237c3e11ce', $$Pandemic Preparedness Capacity Assessment, WHO SEARO, Five Countries$$, $$WHO SEARO$$, (SELECT id FROM organizations WHERE name = $$World Health Organization$$), 2017, 2018, $$Team Leader$$, $$Designed and executed the Joint External Evaluation preparatory assessment for five South-East Asian countries, producing actionable National Action Plans for Health Security aligned with IHR 2005.$$, $$Cross-country assessment produced a comparative capacity scorecard used by WHO SEARO to prioritize technical support; three of the five countries adopted the recommended surveillance upgrades.$$, $$[{"url":"https://picsum.photos/seed/priya-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/priya-portfolio-3-img1/900/600","caption":"Regional preparedness review workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('0fc27fe7-cb28-5f9f-bab1-d667d9441a03', 'ef9da174-4196-4a7d-950f-fb237c3e11ce', $$Health Financing Strategy, Lao PDR$$, $$World Health Organization$$, (SELECT id FROM organizations WHERE name = $$World Health Organization$$), 2021, 2022, $$Lead Health Financing Advisor$$, $$Led the analytical work and stakeholder consultations for Lao PDR's health financing strategy, covering pooling of the national health insurance funds, provider payment reform and a fiscal space analysis for primary care.$$, $$Strategy endorsed by the Ministry of Health; provider payment reform piloted in four provinces.$$, $$[{"url":"https://picsum.photos/seed/dr-priya-nair-health-financing-strategy-lao-pdr-1/900/600","caption":"Consultation with provincial health officers"},{"url":"https://picsum.photos/seed/dr-priya-nair-health-financing-strategy-lao-pdr-2/900/600","caption":"Fiscal space workshop in Vientiane"}]$$::jsonb, $$[]$$::jsonb, NULL, 4),
  ('91122b7f-d2dc-5e92-bfd8-cb02fe01ed54', 'ef9da174-4196-4a7d-950f-fb237c3e11ce', $$NCD Best-Buys Costing, Sri Lanka$$, $$World Health Organization$$, (SELECT id FROM organizations WHERE name = $$World Health Organization$$), 2018, 2018, $$Senior Technical Advisor$$, $$Costed the WHO best-buy interventions for hypertension, diabetes and tobacco control in Sri Lanka and modelled their budget impact over ten years.$$, $$Costing used in the national NCD action plan and in the budget submission for primary care screening.$$, $$[{"url":"https://picsum.photos/seed/dr-priya-nair-ncd-best-buys-costing-sri-lanka-1/900/600","caption":"Costing model review with the NCD unit"}]$$::jsonb, $$[]$$::jsonb, NULL, 5),
  ('e4d3b5c8-a68d-59be-ae23-bebeb3b82d3a', 'ef9da174-4196-4a7d-950f-fb237c3e11ce', $$Medicines Pricing Policy Review, Kenya$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2014, 2015, $$Senior Health Specialist$$, $$Reviewed medicine pricing and procurement policies in Kenya's public sector, compared prices with international reference prices, and set out options for pooled procurement and price regulation.$$, $$Pooled procurement options adopted in the national medicines policy revision.$$, $$[{"url":"https://picsum.photos/seed/dr-priya-nair-medicines-pricing-policy-review-kenya-1/900/600","caption":"Pharmacy price survey in Kisumu"},{"url":"https://picsum.photos/seed/dr-priya-nair-medicines-pricing-policy-review-kenya-2/900/600","caption":"Policy dialogue in Nairobi"}]$$::jsonb, $$[]$$::jsonb, NULL, 6),
  ('f006707a-0d75-516c-a589-0bf31fbf2ca6', 'ef9da174-4196-4a7d-950f-fb237c3e11ce', $$Health Security Investment Plan, Bhutan$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2023, 2023, $$Health Security Consultant$$, $$Prepared a costed investment plan for laboratory, surveillance and emergency response capacities after a joint external evaluation of Bhutan's International Health Regulations core capacities.$$, $$Plan formed the basis of a new health security financing operation.$$, $$[{"url":"https://picsum.photos/seed/dr-priya-nair-health-security-investment-plan-bhutan-1/900/600","caption":"Laboratory capacity visit in Thimphu"}]$$::jsonb, $$[]$$::jsonb, NULL, 7);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6e356ce4-82d2-55d9-9c52-dafbd268e490', 'ef9da174-4196-4a7d-950f-fb237c3e11ce', $$d1bc7d4e-4476-406f-9c55-2643d907467d$$, NULL, $$Dr. Agnes Mwangangi$$, $$World Health Organization$$, $$Unit Head, Health Systems Governance and Financing$$, $$supervisor$$, $$a.mwangangi@who.int$$, (SELECT id FROM organizations WHERE name = $$World Health Organization$$), 2016, 2023, $$Health financing and health systems advisory at WHO headquarters$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Priya for seven years at WHO. She can sit with a finance ministry and a health ministry in the same room and get them to agree on numbers, which is rarer than it sounds. Her Lao health financing strategy is still the reference we use for other countries. She is generous with junior colleagues and very rigorous. I would work with her again on any health financing or primary care reform.$$, $$auto$$, '2026-09-07T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-09-05T16:49:08.421Z'::timestamptz, '2026-09-07T16:34:44.421Z'::timestamptz, '2026-09-07T16:41:56.421Z'::timestamptz, '2026-09-07T16:49:08.421Z'::timestamptz, '2026-09-07T16:49:08.421Z'::timestamptz, '2026-09-08T16:49:08.421Z'::timestamptz, $$66ae5b7ae9a07a6e70a08205994f8696$$, '2026-09-04T16:49:08.421Z'::timestamptz);
INSERT INTO testimonial_events (id, testimonial_id, event, actor, detail, created_at) VALUES
