INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('3327f717-93db-5d82-b2bc-d2bbe837b02f', 'ef9da174-4196-4a7d-950f-fb237c3e11ce', $$edb939b0-c189-4281-8d8f-2865d3749aed$$, NULL, $$Rahul Menon$$, $$World Bank$$, $$Practice Manager, Health, Nutrition and Population$$, $$supervisor$$, $$rmenon@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2010, 2016, $$Health operations in South Asia$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Priya worked in my practice for six years on health operations in Bangladesh and Kenya. Her primary health care investment case for Bangladesh changed how the government budgeted for primary care. She writes clearly, she knows the evidence, and she is honest when the evidence is weak. I would happily work with her again, especially on health financing and medicines policy.$$, $$auto$$, '2026-03-27T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-03-25T16:49:08.421Z'::timestamptz, '2026-03-27T16:34:44.421Z'::timestamptz, '2026-03-27T16:41:56.421Z'::timestamptz, '2026-03-27T16:49:08.421Z'::timestamptz, '2026-03-27T16:49:08.421Z'::timestamptz, '2026-03-28T16:49:08.421Z'::timestamptz, $$d82e0c93fa66025f57ff1b59d020a834$$, '2026-03-24T16:49:08.421Z'::timestamptz);
