INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('362bc1f4-77e5-5e77-bac2-972094793b3e', 'ef9da174-4196-4a7d-950f-fb237c3e11ce', NULL, 'f006707a-0d75-516c-a589-0bf31fbf2ca6', $$Karma Wangchuk$$, $$World Bank$$, $$Senior Health Specialist$$, $$client$$, $$karma.wangchuk@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2023, 2023, $$Health security investment plan for Bhutan$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I contracted Priya to prepare Bhutan's health security investment plan after the joint external evaluation. In six weeks she turned a long list of gaps into a costed plan the ministry could defend to finance. She listened to the laboratory and surveillance teams and built the plan around what they could actually manage. The plan became the basis of our new operation.$$, $$auto$$, NULL, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-09-21T16:49:08.421Z'::timestamptz, '2026-09-23T16:34:44.421Z'::timestamptz, '2026-09-23T16:41:56.421Z'::timestamptz, '2026-09-23T16:49:08.421Z'::timestamptz, '2026-09-23T16:49:08.421Z'::timestamptz, '2026-09-24T16:49:08.421Z'::timestamptz, $$58109575ed0c7487fab5b2f56246fe74$$, '2026-09-20T16:49:08.421Z'::timestamptz);
