-- Amara Diallo
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('8ad3fb21-d648-4528-84ea-2538f0d94867', '388093d4-21e1-413a-a718-4296a10a44fc', $$M&E Framework for USAID Youth Employment Program, Ghana$$, $$USAID$$, (SELECT id FROM organizations WHERE name = $$USAID$$), 2022, 2023, $$Lead M&E Specialist$$, $$Designed a comprehensive performance monitoring plan with 42 indicators aligned to USAID CDCS priorities. Built data collection tools using KoBoToolbox and produced a gender-disaggregated baseline across 6 districts in Greater Accra and Ashanti regions.$$, $$Framework adopted as the program's system of record; 42 indicators tracked quarterly across 6 districts. Gender-disaggregated baseline shifted targeting toward 3 previously-underserved districts, and the design was later reused as a template for two follow-on USAID activities in the region.$$, $$[{"url":"https://picsum.photos/seed/amara-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/amara-portfolio-1-img1/900/600","caption":"Baseline enumeration in Ashanti region"},{"url":"https://picsum.photos/seed/amara-portfolio-1-img2/900/600","caption":"Indicator framework workshop with program staff"}]$$::jsonb, $$[{"url":"https://www.usaid.gov/ghana","label":"Program page (USAID)"},{"url":"https://example.org/ghana-yep-baseline","label":"Baseline report summary"}]$$::jsonb, NULL, 1),
  ('fbd2dcb3-cfbc-46ef-966f-ee41f8303e03', '388093d4-21e1-413a-a718-4296a10a44fc', $$Gender-Sensitive Impact Evaluation, FCDO Skills Programme, Rwanda$$, $$FCDO$$, (SELECT id FROM organizations WHERE name = $$FCDO$$), 2021, 2022, $$Evaluation Team Leader$$, $$Led a mixed-methods impact evaluation assessing the effect of a FCDO-funded TVET program on women's economic empowerment. Oversaw a survey of 1,200 households and qualitative case studies across Kigali and Southern Province.$$, $$Evaluation found a 22-point increase in women's post-training employment; findings informed FCDO's decision to extend the programme for a second phase and to ring-fence childcare stipends for female trainees.$$, $$[{"url":"https://picsum.photos/seed/amara-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/amara-portfolio-2-img1/900/600","caption":"Household survey enumeration, Southern Province"},{"url":"https://picsum.photos/seed/amara-portfolio-2-img2/900/600","caption":"Qualitative case-study interview in Kigali"}]$$::jsonb, $$[{"url":"https://example.org/rwanda-skills-eval","label":"Evaluation brief"}]$$::jsonb, NULL, 2),
  ('d06a9361-b24e-4fb5-9939-bfee01d0ad8a', '388093d4-21e1-413a-a718-4296a10a44fc', $$GBV Prevention Program Review, UN Women, DRC$$, $$UN Women$$, (SELECT id FROM organizations WHERE name = $$UN Women$$), 2019, 2020, $$Senior Evaluator$$, $$Conducted a real-time program review of a multi-site GBV prevention initiative in Eastern DRC, applying feminist evaluation principles and trauma-informed data collection approaches.$$, $$Real-time review reshaped the program's referral pathways mid-cycle, cutting average survivor referral time and expanding trauma-informed intake to all 9 sites.$$, $$[{"url":"https://picsum.photos/seed/amara-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/amara-portfolio-3-img1/900/600","caption":"Community consultation, Eastern DRC"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('1bd65c2b-357e-5d87-bb88-95b55974a3ce', '388093d4-21e1-413a-a718-4296a10a44fc', $$Youth Livelihoods MEL System, Northern Uganda$$, $$Mastercard Foundation$$, (SELECT id FROM organizations WHERE name = $$Mastercard Foundation$$), 2023, 2024, $$MEL Lead$$, $$Designed the monitoring, evaluation and learning system for a youth livelihoods programme reaching 60,000 young people, including the theory of change, indicators disaggregated by gender and disability, and a quarterly learning cycle with implementing partners.$$, $$System live across five partners; first learning review led to a redesign of the apprenticeship component.$$, $$[{"url":"https://picsum.photos/seed/amara-diallo-youth-livelihoods-mel-system-northern-ug-1/900/600","caption":"Theory of change workshop in Gulu"},{"url":"https://picsum.photos/seed/amara-diallo-youth-livelihoods-mel-system-northern-ug-2/900/600","caption":"Youth focus group"}]$$::jsonb, $$[]$$::jsonb, NULL, 4),
  ('07224135-6c40-5e41-a2c5-664ad210c71c', '388093d4-21e1-413a-a718-4296a10a44fc', $$Evidence Review on Women's Economic Empowerment Programmes$$, $$UN Women$$, (SELECT id FROM organizations WHERE name = $$UN Women$$), 2020, 2021, $$Lead Researcher$$, $$Reviewed 48 evaluations of women's economic empowerment programmes in East and West Africa and summarised what worked for savings groups, business training and cash transfers.$$, $$Review used to shape UN Women's regional programme design guidance.$$, $$[{"url":"https://picsum.photos/seed/amara-diallo-evidence-review-on-women-s-economic-empo-1/900/600","caption":"Evidence synthesis workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 5);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6843948e-dcbf-528d-ae35-bd45bbe725a2', '388093d4-21e1-413a-a718-4296a10a44fc', $$3cc2a7cb-dcef-46ba-a5ac-c45f9389e12e$$, NULL, $$Catherine Njoroge$$, $$Palladium$$, $$Programme Director$$, $$supervisor$$, $$c.njoroge@thepalladiumgroup.com$$, (SELECT id FROM organizations WHERE name = $$Palladium$$), 2021, 2024, $$MEAL for an FCDO governance programme in East Africa$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I was Amara's programme director on our FCDO governance programme. She ran MEAL across four countries and made our results framework something teams actually used, not a reporting burden. She is especially good at gender-disaggregated data and at explaining findings to people who are not evaluators. I would work with her again on any M&E or learning assignment.$$, $$auto$$, '2026-08-20T16:49:08.421Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-18T16:49:08.421Z'::timestamptz, '2026-08-20T16:34:44.421Z'::timestamptz, '2026-08-20T16:41:56.421Z'::timestamptz, '2026-08-20T16:49:08.421Z'::timestamptz, '2026-08-20T16:49:08.421Z'::timestamptz, '2026-08-21T16:49:08.421Z'::timestamptz, $$3cdddd44407b24f2a75dd2e8ecf85264$$, '2026-08-17T16:49:08.421Z'::timestamptz);
