INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('31c54c5b-909a-5af4-a074-2a5a5d4fb242', '388093d4-21e1-413a-a718-4296a10a44fc', $$d7c3a98c-c934-4a79-a905-360a8243710e$$, NULL, $$Fatou Ndiaye$$, $$UN Women$$, $$Regional Evaluation Specialist$$, $$supervisor$$, $$fatou.ndiaye@unwomen.org$$, (SELECT id FROM organizations WHERE name = $$UN Women$$), 2018, 2021, $$Data systems and GBV programme review$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Amara worked with me at UN Women for three years. She designed the data systems for our GBV programmes and led the programme review in the DRC under difficult security conditions. She is careful with survivors' data and thoughtful about ethics. Her evidence review on women's economic empowerment is still on my desk. I would work with her again without hesitation.$$, $$auto$$, '2026-05-26T16:49:08.421Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-05-24T16:49:08.421Z'::timestamptz, '2026-05-26T16:34:44.421Z'::timestamptz, '2026-05-26T16:41:56.421Z'::timestamptz, '2026-05-26T16:49:08.421Z'::timestamptz, '2026-05-26T16:49:08.421Z'::timestamptz, '2026-05-27T16:49:08.421Z'::timestamptz, $$67d7a5e773d98e0cc90fb5e46334e5e1$$, '2026-05-23T16:49:08.421Z'::timestamptz);
