INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6635192e-5ae0-5864-abf6-0b77740fcca9', '388093d4-21e1-413a-a718-4296a10a44fc', NULL, '8ad3fb21-d648-4528-84ea-2538f0d94867', $$Michael Owusu$$, $$USAID$$, $$Senior Monitoring and Evaluation Advisor$$, $$client$$, $$mowusu@usaid.gov$$, (SELECT id FROM organizations WHERE name = $$USAID$$), 2022, 2023, $$M&E framework for a youth employment programme in Ghana$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We contracted Amara to design the M&E framework for our youth employment programme in Ghana. She delivered on time, consulted the implementing partners properly, and built indicators that captured young women's outcomes, which earlier frameworks had missed. Her performance monitoring plan passed our review with very few comments.$$, $$auto$$, NULL, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-15T16:49:08.421Z'::timestamptz, '2026-07-17T16:34:44.421Z'::timestamptz, '2026-07-17T16:41:56.421Z'::timestamptz, '2026-07-17T16:49:08.421Z'::timestamptz, '2026-07-17T16:49:08.421Z'::timestamptz, '2026-07-18T16:49:08.421Z'::timestamptz, $$c54cae6c33277ade3871d4fec41aa52a$$, '2026-07-14T16:49:08.421Z'::timestamptz);
