-- Dr. Sunita Patel
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('f8574058-6132-4b82-b57e-43ecb6d82ce3', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', $$Shock-Responsive Social Protection Assessment, Philippines$$, $$ADB$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2022, 2023, $$Lead Social Protection Specialist$$, $$Led a comprehensive assessment of the Philippines' 4Ps conditional cash transfer program's capacity to respond to typhoon shocks, producing a shock-responsiveness roadmap adopted by the Department of Social Welfare and Development.$$, $$Assessment produced a shock-responsiveness roadmap adopted by the Department of Social Welfare and Development; informed protocols for scaling cash transfers during typhoon response.$$, $$[{"url":"https://picsum.photos/seed/sunita-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/sunita-portfolio-1-img1/900/600","caption":"Post-disaster cash-transfer field visit"},{"url":"https://picsum.photos/seed/sunita-portfolio-1-img2/900/600","caption":"Systems workshop with DSWD officials"}]$$::jsonb, $$[{"url":"https://www.dswd.gov.ph/","label":"DSWD Philippines"},{"url":"https://example.org/philippines-srsp","label":"Roadmap summary"}]$$::jsonb, NULL, 1),
  ('3d7111c6-f410-4a5d-8cf8-64c79c606eee', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', $$Gender-Transformative Cash Transfer Design, UNICEF, Indonesia$$, $$UNICEF Indonesia$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2014, 2016, $$Gender & Social Protection Advisor$$, $$Designed gender-transformative features for Indonesia's Program Keluarga Harapan (PKH) cash transfer, including care economy provisions, domestic violence referral linkages, and women's financial inclusion components reaching 9.2M beneficiary families.$$, $$Redesign embedded care-economy provisions and GBV referral linkages into a cash-transfer program reaching 9.2M families; gender-transformative features adopted into program guidelines.$$, $$[{"url":"https://picsum.photos/seed/sunita-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/sunita-portfolio-2-img1/900/600","caption":"Beneficiary consultation, Indonesia"}]$$::jsonb, $$[{"url":"https://www.unicef.org/indonesia/","label":"UNICEF Indonesia"}]$$::jsonb, NULL, 2),
  ('414e96af-77d6-439d-b542-192d9fef71d7', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', $$Social Protection Floor Costing Study, ADB, Cambodia$$, $$ADB$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2019, 2020, $$Social Protection Economist$$, $$Developed the costing model and fiscal space analysis for Cambodia's Social Protection Floor strategy, modelling five benefit package options against projected GDP growth, donor co-financing, and domestic revenue scenarios to 2035.$$, $$Costing study modeled five benefit-package options against fiscal-space scenarios to 2035; provided the evidence base for Cambodia's social-protection floor strategy.$$, $$[{"url":"https://picsum.photos/seed/sunita-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/sunita-portfolio-3-img1/900/600","caption":"Fiscal-space modeling workshop, Phnom Penh"}]$$::jsonb, $$[{"url":"https://www.adb.org/","label":"ADB"}]$$::jsonb, NULL, 3),
  ('9b98b28c-3d18-5edc-8376-4a8bc762b253', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', $$Disaster Risk Finance for Adaptive Social Protection, Fiji$$, $$Asian Development Bank$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2023, 2024, $$Social Protection Specialist$$, $$Designed the triggers, pre-arranged financing and payment procedures that allow Fiji's social assistance programmes to top up payments after a cyclone, linking the national disaster risk finance strategy to the social welfare database.$$, $$Top-up protocol approved by the Ministry of Finance; first activation reached 23,000 households within ten days of a cyclone.$$, $$[{"url":"https://picsum.photos/seed/dr-sunita-patel-disaster-risk-finance-for-adaptive-socia-1/900/600","caption":"Payment simulation with welfare officers"},{"url":"https://picsum.photos/seed/dr-sunita-patel-disaster-risk-finance-for-adaptive-socia-2/900/600","caption":"Validation workshop in Suva"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('cc37cc5f-0225-5528-91eb-8b69808af191', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', $$91d5b0d3-c4e2-4598-ab8b-3833260198cf$$, NULL, $$Maria Theresa Santos$$, $$Asian Development Bank$$, $$Principal Social Sector Specialist$$, $$supervisor$$, $$mtsantos@adb.org$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2017, 2024, $$Social protection operations in Southeast Asia and the Pacific$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Sunita has been our lead social protection consultant for seven years. She is one of very few people who understands both safety net operations and disaster risk finance. Her shock-responsive assessment in the Philippines shaped our support after Typhoon Odette, and the Fiji top-up protocol worked the first time it was used. I would work with her again on any adaptive social protection assignment.$$, $$auto$$, '2026-08-12T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-10T16:49:08.421Z'::timestamptz, '2026-08-12T16:34:44.421Z'::timestamptz, '2026-08-12T16:41:56.421Z'::timestamptz, '2026-08-12T16:49:08.421Z'::timestamptz, '2026-08-12T16:49:08.421Z'::timestamptz, '2026-08-13T16:49:08.421Z'::timestamptz, $$2e8ab0a2a271db1296fb8671eb8ff327$$, '2026-08-09T16:49:08.421Z'::timestamptz);
