INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6a9f5b4a-d62c-593e-804d-93694a58ffab', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', $$d670c778-bbb8-467e-ba9f-cf297b9c284f$$, NULL, $$Kenji Watanabe$$, $$UNICEF$$, $$Chief of Social Policy$$, $$supervisor$$, $$kwatanabe@unicef.org$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2011, 2017, $$Social policy in East Asia and the Pacific$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Sunita at UNICEF's regional office. She designed a gender-transformative cash transfer in Indonesia that the government later scaled nationally. She has deep technical knowledge and a real commitment to the poorest households. She writes well and she builds lasting relationships with government counterparts. I would gladly work with her again.$$, $$auto$$, '2026-02-05T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-02-03T16:49:08.421Z'::timestamptz, '2026-02-05T16:34:44.421Z'::timestamptz, '2026-02-05T16:41:56.421Z'::timestamptz, '2026-02-05T16:49:08.421Z'::timestamptz, '2026-02-05T16:49:08.421Z'::timestamptz, '2026-02-06T16:49:08.421Z'::timestamptz, $$a8c00cd78c2277a2b46b3565e1e6d390$$, '2026-02-02T16:49:08.421Z'::timestamptz);
