INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('76a76bf3-3ba0-5eae-bf80-a4078d989a05', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the gender-transformative cash transfer design in Indonesia. My role was to lead the design and the pilot evaluation. The government later scaled the design nationally, and payments to mothers became the default.$$, 20),
  ('184e6c28-f38d-51ad-b68f-d5e2152b4022', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] When I first worked in Fiji I didn't know the Pacific welfare system. I spent time with welfare officers in the outer islands and learned that payment logistics, not targeting, was the real constraint after a cyclone.$$, 20),
  ('6c96d0ad-e8c2-5f98-9daf-adbb63885154', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] Our assessment in Cambodia found that the proposed social protection floor was unaffordable. I presented costed alternatives alongside the bad news, so the ministry could choose a phased path rather than abandon the idea.$$, 20),
  ('8a246023-7408-5822-9ee6-75d8ed8f6fd1', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I always pair with national researchers and civil servants. In the Philippines my counterpart at the welfare department co-presented every finding, and that made the recommendations hers as much as mine.$$, 20),
  ('6646a818-644a-5f59-bed8-fe6d3a0b75b2', 'ade0f4c7-c4a6-453c-a5c4-ccf933c17362', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in microsimulation of cash transfer options. It is not the right tool when the data on household incomes is very poor or out of date; then qualitative targeting reviews are more honest.$$, 20);
