-- Dr. Kwame Asante
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('55a67cf1-779e-43cd-98b0-dc733679fc8c', 'a241c771-1cae-47db-a6dd-a01f98742b05', $$National Basic Education Curriculum Reform, Ghana Education Service$$, $$Ghana Education Service$$, (SELECT id FROM organizations WHERE name = $$Ghana Education Service$$), 2018, 2022, $$Curriculum Development Lead$$, $$Led the Ghana Education Service's comprehensive review and redesign of the K–9 curriculum, introducing competency-based learning outcomes, STEM integration, and a revised civic education strand. Trained 1,200 master teachers as curriculum implementation coaches.$$, $$Standards-based curriculum rolled out nationally across primary grades; accompanying teacher-orientation package reached tens of thousands of teachers ahead of implementation.$$, $$[{"url":"https://picsum.photos/seed/kwame-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/kwame-portfolio-1-img1/900/600","caption":"Curriculum co-design workshop with teachers"},{"url":"https://picsum.photos/seed/kwame-portfolio-1-img2/900/600","caption":"Pilot classroom, Greater Accra"}]$$::jsonb, $$[{"url":"https://ges.gov.gh/","label":"Ghana Education Service"}]$$::jsonb, NULL, 1),
  ('34d53561-9f5d-4713-99cc-3f0fc55988ee', 'a241c771-1cae-47db-a6dd-a01f98742b05', $$Teacher Professional Development Framework, UNICEF Sierra Leone$$, $$UNICEF Sierra Leone$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2016, 2017, $$Education Systems Advisor$$, $$Designed Sierra Leone's National Teacher Professional Development Framework post-Ebola, establishing in-service training standards, a continuous professional learning record system, and regional training centre network.$$, $$Framework established a national in-service teacher-training model; adopted by the Teaching Service Commission as the basis for continuous professional development.$$, $$[{"url":"https://picsum.photos/seed/kwame-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/kwame-portfolio-2-img1/900/600","caption":"Teacher training-of-trainers session, Freetown"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('3d7f81a5-52ca-4350-b61f-bf31e9b2f110', 'a241c771-1cae-47db-a6dd-a01f98742b05', $$Learning Assessment System Design, GPE Program, Liberia$$, $$Global Partnership for Education$$, (SELECT id FROM organizations WHERE name = $$Global Partnership for Education$$), 2014, 2015, $$Assessment Specialist$$, $$Designed Liberia's national early grade reading and mathematics assessment system, including item bank development, standardization protocols, and a school-level reporting dashboard for district education officers.$$, $$Designed Liberia's first standardized early-grade learning assessment; results gave the Ministry a baseline for tracking literacy and numeracy gains over time.$$, $$[{"url":"https://picsum.photos/seed/kwame-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/kwame-portfolio-3-img1/900/600","caption":"Early-grade assessment administration"}]$$::jsonb, $$[{"url":"https://www.globalpartnership.org/","label":"Global Partnership for Education"}]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6cf17f13-0cb9-5691-bf6c-e75d0b27e9cd', 'a241c771-1cae-47db-a6dd-a01f98742b05', $$2cff71f3-c022-4499-8ba6-88c67bc67b0d$$, NULL, $$Dr. Mathilde Ouellet$$, $$UNESCO$$, $$Senior Education Policy Specialist$$, $$supervisor$$, $$m.ouellet@unesco.org$$, (SELECT id FROM organizations WHERE name = $$UNESCO$$), 2012, 2018, $$Education sector planning at UNESCO IIEP$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Kwame for six years at IIEP. He led sector planning support for several West African ministries and trained their planners with great patience. He is respected by ministers and teachers alike. His curriculum work in Ghana built directly on what he learned with us. I would work with him again on any education sector plan or curriculum reform.$$, $$auto$$, '2026-04-26T16:49:08.421Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-04-24T16:49:08.421Z'::timestamptz, '2026-04-26T16:34:44.421Z'::timestamptz, '2026-04-26T16:41:56.421Z'::timestamptz, '2026-04-26T16:49:08.421Z'::timestamptz, '2026-04-26T16:49:08.421Z'::timestamptz, '2026-04-27T16:49:08.421Z'::timestamptz, $$57be9e5fcd97e169417f1ff8ff5b3305$$, '2026-04-23T16:49:08.421Z'::timestamptz);
