-- Fatima Al-Rashid
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('c7ac3f34-4611-4db4-9f83-25c8fae6cfcd', '9169e962-d148-4d97-92d9-e4cb37209044', $$Durable Solutions Research, Syrian Refugees in Jordan, UNHCR$$, $$UNHCR Jordan$$, (SELECT id FROM organizations WHERE name = $$UNHCR$$), 2024, NULL, $$Lead Researcher$$, $$Led a qualitative research study with 180 Syrian refugee households in Amman and Zarqa on intentions and barriers around voluntary return, local integration, and third-country resettlement, informing UNHCR Jordan's durable solutions strategy.$$, $$Mixed-methods study of 800+ households informed UNHCR's durable-solutions strategy; findings on livelihood barriers shaped a revised work-permit advocacy agenda.$$, $$[{"url":"https://picsum.photos/seed/fatima-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/fatima-portfolio-1-img1/900/600","caption":"Household interview, Zaatari-area community"},{"url":"https://picsum.photos/seed/fatima-portfolio-1-img2/900/600","caption":"Research team debrief, Amman"}]$$::jsonb, $$[{"url":"https://www.unhcr.org/jordan","label":"UNHCR Jordan"}]$$::jsonb, NULL, 1),
  ('a40a44c3-06ac-4bdd-b098-b5d914f5a6f9', '9169e962-d148-4d97-92d9-e4cb37209044', $$GBV Response Program Learning Study, IRC, Lebanon$$, $$IRC$$, (SELECT id FROM organizations WHERE name = $$International Rescue Committee$$), 2022, 2023, $$Research Consultant$$, $$Conducted a learning study on the effectiveness of IRC's cash-plus GBV prevention model in Beirut and Bekaa Valley, using feminist participatory methods and survivor-centred analysis frameworks.$$, $$Learning study identified access barriers for adolescent survivors; recommendations were adopted into IRC's case-management protocols across its Lebanon sites.$$, $$[{"url":"https://picsum.photos/seed/fatima-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/fatima-portfolio-2-img1/900/600","caption":"Safe-space facility assessment, Bekaa Valley"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('165be5cc-90d8-4938-be7b-32b7f3807360', '9169e962-d148-4d97-92d9-e4cb37209044', $$Legal Identity and Service Access Research, South Sudanese Refugees, Kenya$$, $$IRC$$, (SELECT id FROM organizations WHERE name = $$International Rescue Committee$$), 2021, 2021, $$Field Research Lead$$, $$Managed field data collection and analysis for a mixed-methods study on documentation barriers faced by South Sudanese refugees in Kakuma and Nairobi, producing policy recommendations adopted by UNHCR Kenya.$$, $$Research documented civil-documentation gaps blocking service access; evidence supported a UNHCR-government dialogue on birth-registration for refugee children.$$, $$[{"url":"https://picsum.photos/seed/fatima-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/fatima-portfolio-3-img1/900/600","caption":"Field research, Kalobeyei settlement"}]$$::jsonb, $$[{"url":"https://example.org/kenya-legal-identity","label":"Research brief"}]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('d13c3cbd-a371-5ca6-8154-d3c990c0eb33', '9169e962-d148-4d97-92d9-e4cb37209044', $$d2b2a7f8-6111-4539-aca9-0a24335f9ccc$$, NULL, $$Dr. Hana Saleh$$, $$UNHCR$$, $$Senior Protection Officer$$, $$supervisor$$, $$h.saleh@unhcr.org$$, (SELECT id FROM organizations WHERE name = $$UNHCR$$), 2024, 2025, $$Durable solutions research with Syrian refugees in Jordan$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Fatima has worked with my team on durable solutions research for Syrian refugees in Jordan. Her interviews are ethical, careful and humane, and refugees trust her. She turns long transcripts into findings that our managers can act on. She is early in her career but already one of the best qualitative researchers I have worked with. I would work with her again.$$, $$auto$$, '2026-09-18T16:49:08.421Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-09-16T16:49:08.421Z'::timestamptz, '2026-09-18T16:34:44.421Z'::timestamptz, '2026-09-18T16:41:56.421Z'::timestamptz, '2026-09-18T16:49:08.421Z'::timestamptz, '2026-09-18T16:49:08.421Z'::timestamptz, '2026-09-19T16:49:08.421Z'::timestamptz, $$b8f820af9e040bc62ca88a1c4a22cbf4$$, '2026-09-15T16:49:08.421Z'::timestamptz);
