-- Sofia Reyes
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('bd5da32c-019e-4e71-8a6a-9e773157c21b', '2132cd88-8240-49d9-aa2c-20370a44581a', $$Municipal Peace Plan Design, Tumaco & Buenaventura, Colombia$$, $$Search for Common Ground$$, (SELECT id FROM organizations WHERE name = $$Search for Common Ground$$), 2017, 2018, $$Peacebuilding Advisor$$, $$Facilitated a participatory process engaging 340 community representatives to co-design municipal peace plans aligned with Colombia's territorial peace framework, covering land restitution, victim reparations, and community security.$$, $$Participatory peace plans adopted by both municipal governments; process convened over 40 community organizations and established standing citizen-security roundtables that continued past the engagement.$$, $$[{"url":"https://picsum.photos/seed/sofia-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/sofia-portfolio-1-img1/900/600","caption":"Community peace-planning workshop, Tumaco"},{"url":"https://picsum.photos/seed/sofia-portfolio-1-img2/900/600","caption":"Municipal validation session, Buenaventura"}]$$::jsonb, $$[{"url":"https://example.org/colombia-municipal-peace","label":"Project overview"}]$$::jsonb, NULL, 1),
  ('7b85f34c-6105-482c-8cda-b93dbaafa284', '2132cd88-8240-49d9-aa2c-20370a44581a', $$Conflict Sensitivity Assessment, USAID Economic Recovery Program, El Salvador$$, $$USAID$$, (SELECT id FROM organizations WHERE name = $$USAID$$), 2020, 2021, $$Conflict Analyst$$, $$Conducted a do-no-harm conflict sensitivity analysis for a $28M USAID workforce development program operating in high-violence municipalities, producing a conflict mitigation plan and training staff on conflict-sensitive implementation.$$, $$Assessment reshaped program siting to avoid inadvertently reinforcing gang-controlled territories; do-no-harm guidance was integrated into all subsequent grant-making.$$, $$[{"url":"https://picsum.photos/seed/sofia-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/sofia-portfolio-2-img1/900/600","caption":"Key-informant interview, San Salvador"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('bf00a3bd-3e93-4c8a-809c-27501b75b7b5', '2132cd88-8240-49d9-aa2c-20370a44581a', $$Ex-Combatant Reintegration Evaluation, UNODC, Colombia$$, $$UNODC$$, (SELECT id FROM organizations WHERE name = $$UNODC$$), 2018, 2018, $$Lead Evaluator$$, $$Led the midterm evaluation of a FARC ex-combatant reintegration program in six Zonas Veredales, assessing psychosocial, economic, and community acceptance dimensions using mixed methods.$$, $$Evaluation documented a 3-year reintegration trajectory and surfaced gaps in rural economic opportunity; recommendations informed UNODC's redesign of livelihood support.$$, $$[{"url":"https://picsum.photos/seed/sofia-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/sofia-portfolio-3-img1/900/600","caption":"Fieldwork with reintegration cooperatives"}]$$::jsonb, $$[{"url":"https://example.org/colombia-reintegration-eval","label":"Evaluation summary"}]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('ed4a51b2-569c-51dd-b62d-9f0761d37937', '2132cd88-8240-49d9-aa2c-20370a44581a', $$4a58ec0d-d57a-4c39-a1b2-59150430fac1$$, NULL, $$Andrea Gutiérrez$$, $$Search for Common Ground$$, $$Regional Director, Latin America$$, $$supervisor$$, $$agutierrez@sfcg.org$$, (SELECT id FROM organizations WHERE name = $$Search for Common Ground$$), 2015, 2019, $$Peacebuilding programmes in Colombia$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Sofia managed our Colombia programme for four years. She led the municipal peace plans in Tumaco and Buenaventura with communities that had every reason to distrust outsiders, and she earned their trust. She is calm, principled and very good with local authorities. I would work with her again on peacebuilding, reintegration or conflict sensitivity work.$$, $$auto$$, '2026-03-07T16:49:08.421Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-03-05T16:49:08.421Z'::timestamptz, '2026-03-07T16:34:44.421Z'::timestamptz, '2026-03-07T16:41:56.421Z'::timestamptz, '2026-03-07T16:49:08.421Z'::timestamptz, '2026-03-07T16:49:08.421Z'::timestamptz, '2026-03-08T16:49:08.421Z'::timestamptz, $$05c35ccb4c7afaaac0c9b1a542e6df84$$, '2026-03-04T16:49:08.421Z'::timestamptz);
