-- James Okafor
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('5a5fa261-cc65-4b8c-98fa-e38625ad451b', '09b0edb2-bee9-4e9c-91ce-77e2d8e6f7cc', $$Coastal Erosion Vulnerability Atlas, Niger Delta Region$$, $$UNDP Nigeria$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2022, 2022, $$GIS Analyst$$, $$Produced a 1:25,000 vulnerability atlas of the Niger Delta coastline using Sentinel-2 imagery and tidal modelling, identifying 47 high-risk communities for climate adaptation investment.$$, $$Atlas mapped erosion risk across 120km of coastline; used by state planning authorities to reprioritize shoreline protection investment and to flag 4 high-risk settlements for managed relocation planning.$$, $$[{"url":"https://picsum.photos/seed/james-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/james-portfolio-1-img1/900/600","caption":"Shoreline change detection, 2000–2023"},{"url":"https://picsum.photos/seed/james-portfolio-1-img2/900/600","caption":"Field ground-truthing of erosion hotspots"}]$$::jsonb, $$[{"url":"https://example.org/niger-delta-atlas","label":"Interactive atlas (demo)"}]$$::jsonb, NULL, 1),
  ('26e17e30-6893-423f-891a-30f380ec0b04', '09b0edb2-bee9-4e9c-91ce-77e2d8e6f7cc', $$Deforestation Monitoring Dashboard, SERVIR West Africa$$, $$SERVIR West Africa$$, NULL, 2023, NULL, $$Geospatial Developer$$, $$Built a real-time deforestation alert dashboard using Google Earth Engine and Landsat time-series data, enabling six partner governments to track forest cover change at monthly intervals.$$, $$Near-real-time dashboard adopted by two national forestry agencies; automated alerts cut the lag between canopy-loss detection and field response from weeks to days.$$, $$[{"url":"https://picsum.photos/seed/james-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/james-portfolio-2-img1/900/600","caption":"Forest-loss alert dashboard interface"},{"url":"https://picsum.photos/seed/james-portfolio-2-img2/900/600","caption":"Training forestry staff on alert triage"}]$$::jsonb, $$[{"url":"https://servirglobal.net/","label":"SERVIR Global"},{"url":"https://example.org/servir-deforestation","label":"Dashboard walkthrough"}]$$::jsonb, NULL, 2),
  ('78dd001e-9b1f-4eda-89b4-18805d6a3030', '09b0edb2-bee9-4e9c-91ce-77e2d8e6f7cc', $$Urban Heat Island Mapping, UNDP Cities Program, Kano$$, $$UNDP Nigeria$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2021, 2022, $$Remote Sensing Analyst$$, $$Mapped land surface temperature differentials across Kano city using MODIS and Landsat thermal data to inform urban greening and climate-resilient design recommendations.$$, $$Heat-island mapping identified priority wards for green-infrastructure investment; findings fed into Kano's urban resilience plan and a pilot tree-planting corridor.$$, $$[{"url":"https://picsum.photos/seed/james-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/james-portfolio-3-img1/900/600","caption":"Land-surface temperature map, Kano metropolitan area"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
