INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('5bae029b-94af-4d5e-b75b-074b256babd2', 'a8161c80-db01-47c6-ba5b-ec4f86883950', $$RCT Evaluation of Conditional Cash Transfer Scale-Up, Peru$$, $$GRADE$$, (SELECT id FROM organizations WHERE name = $$Grupo de Análisis para el Desarrollo$$), 2020, 2022, $$Quantitative Analyst$$, $$Supported the evaluation design and data analysis for an RCT assessing the impact of the Juntos CCT program expansion on child nutrition and school enrollment in rural Andean communities, using administrative data from 420,000 beneficiaries.$$, $$Randomized evaluation credibly estimated program effects on school attendance and nutrition; results informed the government's decision to expand coverage to additional regions.$$, $$[{"url":"https://picsum.photos/seed/pablo-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/pablo-portfolio-1-img1/900/600","caption":"Field survey enumeration, rural Peru"},{"url":"https://picsum.photos/seed/pablo-portfolio-1-img2/900/600","caption":"Data-quality review with field team"}]$$::jsonb, $$[{"url":"https://www.povertyactionlab.org/","label":"J-PAL"},{"url":"https://example.org/peru-cct-rct","label":"Evaluation summary"}]$$::jsonb, NULL, 1),
  ('12560eb4-1d47-402f-af40-57c008aee6d0', 'a8161c80-db01-47c6-ba5b-ec4f86883950', $$Labor Market Impact Evaluation, Youth Employment Program, Ecuador$$, $$J-PAL LAC$$, (SELECT id FROM organizations WHERE name = $$J-PAL$$), 2023, 2024, $$Impact Evaluation Specialist$$, $$Designed a regression discontinuity evaluation of Ecuador's Jóvenes Construyendo el Futuro vocational training program, building the empirical strategy, data pipeline, and analytical code in Stata and R.$$, $$Evaluation isolated program impact on youth earnings and formal employment; cost-effectiveness findings shaped the design of the program's next phase.$$, $$[{"url":"https://picsum.photos/seed/pablo-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/pablo-portfolio-2-img1/900/600","caption":"Youth participant tracer survey, Ecuador"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('94b5f091-c11c-48da-bd2a-b20f5c146c0c', 'a8161c80-db01-47c6-ba5b-ec4f86883950', $$Social Registry Data Quality Assessment, IDB, Bolivia$$, $$IDB$$, (SELECT id FROM organizations WHERE name = $$Inter-American Development Bank$$), 2024, 2024, $$Data Systems Analyst$$, $$Conducted a data quality and coverage assessment of Bolivia's Registro Único de Beneficiarios social registry, identifying targeting errors and developing a de-duplication protocol that improved registry accuracy by 18%.$$, $$Assessment quantified targeting errors in the social registry and recommended fixes; adopted improvements tightened eligibility accuracy for social programs.$$, $$[{"url":"https://picsum.photos/seed/pablo-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/pablo-portfolio-3-img1/900/600","caption":"Social-registry data audit"}]$$::jsonb, $$[{"url":"https://www.iadb.org/en","label":"IDB"}]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('5838ee3c-008f-5af2-8460-e8335ba3ebc0', 'a8161c80-db01-47c6-ba5b-ec4f86883950', $$f86ed183-2d96-41d5-beeb-8ad49d76b41a$$, NULL, $$Dr. Lucía Fernández$$, $$J-PAL$$, $$Research Manager$$, $$supervisor$$, $$lfernandez@povertyactionlab.org$$, (SELECT id FROM organizations WHERE name = $$J-PAL$$), 2022, 2025, $$Randomized evaluations of social programmes in Latin America$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Pablo has worked in my team at J-PAL Latin America since 2022. He runs our data work on two randomized evaluations and his code is clean and reproducible. He spotted a sampling problem in the Ecuador youth employment study early enough to fix it. He is careful, curious and reliable. I would work with him again on any quantitative evaluation.$$, $$auto$$, '2026-08-26T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-24T16:49:08.421Z'::timestamptz, '2026-08-26T16:34:44.421Z'::timestamptz, '2026-08-26T16:41:56.421Z'::timestamptz, '2026-08-26T16:49:08.421Z'::timestamptz, '2026-08-26T16:49:08.421Z'::timestamptz, '2026-08-27T16:49:08.421Z'::timestamptz, $$0b48c7d24f60e25b4724b86b98183b04$$, '2026-08-23T16:49:08.421Z'::timestamptz);
