-- Lena Hoffmann
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('aa890f8c-7b9a-4267-8beb-4e147e2ba9ae', '0b3dca45-f309-4196-b83d-8840e915a177', $$National Open Data Portal, Government of Ukraine$$, $$GIZ$$, (SELECT id FROM organizations WHERE name = $$GIZ$$), 2015, 2017, $$Technical Lead & Project Director$$, $$Led the design, build, and launch of data.gov.ua — Ukraine's national open data portal — managing a multidisciplinary team of developers, UX designers, and policy advisors to release 3,000+ government datasets under open licence.$$, $$Portal launched with 1,000+ datasets across 20 ministries; became a reference implementation cited in regional open-government reviews and sustained an active civic-tech developer community.$$, $$[{"url":"https://picsum.photos/seed/lena-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/lena-portfolio-1-img1/900/600","caption":"Portal data-catalog interface"},{"url":"https://picsum.photos/seed/lena-portfolio-1-img2/900/600","caption":"Open-data hackathon with civic developers"}]$$::jsonb, $$[{"url":"https://example.org/ukraine-open-data","label":"Open data portal (example)"},{"url":"https://example.org/ukraine-odp-casestudy","label":"Case study"}]$$::jsonb, NULL, 1),
  ('3e32b0f7-9eb6-42b3-9a84-a9816cd5eec6', '0b3dca45-f309-4196-b83d-8840e915a177', $$Digital Identity Framework, Government of Rwanda$$, $$GIZ$$, (SELECT id FROM organizations WHERE name = $$GIZ$$), 2019, 2020, $$Policy & Standards Advisor$$, $$Advised the Rwanda Utilities Regulatory Authority on the legal and technical standards for a privacy-preserving national digital identity system, drawing on GDPR principles and NIST digital identity guidelines.$$, $$Framework set the interoperability and privacy standards later adopted for national digital-ID rollout; privacy-by-design provisions were written into the enabling regulation.$$, $$[{"url":"https://picsum.photos/seed/lena-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/lena-portfolio-2-img1/900/600","caption":"Standards workshop with government stakeholders"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('a6610471-d045-414e-9649-774d1ec006d7', '0b3dca45-f309-4196-b83d-8840e915a177', $$Anti-Corruption Digital Disclosure System, GIZ Georgia$$, $$GIZ$$, (SELECT id FROM organizations WHERE name = $$GIZ$$), 2017, 2018, $$Systems Architect$$, $$Designed an asset declaration and conflict-of-interest disclosure platform for Georgian public officials, integrating with the Civil Service Bureau's HR systems and enabling public search of declarations.$$, $$Asset-disclosure system brought 10,000+ officials into structured online filing; automated conflict-of-interest flags gave the anti-corruption bureau a triage queue it previously lacked.$$, $$[{"url":"https://picsum.photos/seed/lena-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/lena-portfolio-3-img1/900/600","caption":"Disclosure system architecture diagram"}]$$::jsonb, $$[{"url":"https://example.org/georgia-disclosure","label":"System overview"}]$$::jsonb, NULL, 3),
  ('37c2eedd-e643-51bc-841a-038700501008', '0b3dca45-f309-4196-b83d-8840e915a177', $$Civic Tech Fund for Civil Society, Western Balkans$$, $$GIZ$$, (SELECT id FROM organizations WHERE name = $$GIZ$$), 2021, 2022, $$Fund Design Lead$$, $$Designed a small grants fund for civic tech organisations in four Western Balkan countries, including selection criteria, mentoring and a shared open-source toolkit for budget and procurement monitoring.$$, $$22 organisations funded; nine tools still maintained two years later.$$, $$[{"url":"https://picsum.photos/seed/lena-hoffmann-civic-tech-fund-for-civil-society-wester-1/900/600","caption":"Civic tech meet-up in Sarajevo"},{"url":"https://picsum.photos/seed/lena-hoffmann-civic-tech-fund-for-civil-society-wester-2/900/600","caption":"Mentoring session"}]$$::jsonb, $$[]$$::jsonb, NULL, 4),
  ('a25a5875-49cd-5c11-8709-166822b94193', '0b3dca45-f309-4196-b83d-8840e915a177', $$Fact-Checking Network Support, Ukraine$$, $$European Union$$, (SELECT id FROM organizations WHERE name = $$European Union$$), 2019, 2020, $$Digital Governance Advisor$$, $$Advised an EU media development programme on data tools for regional fact-checking newsrooms, including access to government open data and a shared verification workflow.$$, $$Eight newsrooms trained; open data requests to ministries tripled.$$, $$[{"url":"https://picsum.photos/seed/lena-hoffmann-fact-checking-network-support-ukraine-1/900/600","caption":"Newsroom training in Lviv"}]$$::jsonb, $$[]$$::jsonb, NULL, 5),
  ('468429de-1279-53d2-b0f6-be96753ccde7', '0b3dca45-f309-4196-b83d-8840e915a177', $$Digital Public Infrastructure Roadmap, Uzbekistan$$, $$GIZ$$, (SELECT id FROM organizations WHERE name = $$GIZ$$), 2023, 2024, $$Senior Advisor$$, $$Led the assessment of Uzbekistan's digital identity, data exchange and payments components and drafted a phased roadmap for digital public infrastructure with the Ministry of Digital Technologies.$$, $$Roadmap adopted; data exchange layer prioritised for the 2025 budget.$$, $$[{"url":"https://picsum.photos/seed/lena-hoffmann-digital-public-infrastructure-roadmap-uz-1/900/600","caption":"Roadmap workshop in Tashkent"},{"url":"https://picsum.photos/seed/lena-hoffmann-digital-public-infrastructure-roadmap-uz-2/900/600","caption":"Data exchange architecture review"}]$$::jsonb, $$[]$$::jsonb, NULL, 6),
  ('b08aaaaf-e00f-543d-9004-d803515154fa', '0b3dca45-f309-4196-b83d-8840e915a177', $$Open Budget Portal, Moldova$$, $$European Union$$, (SELECT id FROM organizations WHERE name = $$European Union$$), 2012, 2013, $$Policy Consultant$$, $$Supported the Ministry of Finance to publish budget execution data as open data and design a citizen-facing budget portal, with user testing among journalists and civil society.$$, $$Portal launched in 2013; Moldova's Open Budget Index score rose by 12 points.$$, $$[{"url":"https://picsum.photos/seed/lena-hoffmann-open-budget-portal-moldova-1/900/600","caption":"User testing with journalists"}]$$::jsonb, $$[]$$::jsonb, NULL, 7);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('9934fa75-5c25-5172-96d3-3c305f240c95', '0b3dca45-f309-4196-b83d-8840e915a177', $$29221515-a969-4788-a801-ae4955e49146$$, NULL, $$Dr. Markus Feldmann$$, $$GIZ$$, $$Head of Section, Digital Transformation$$, $$supervisor$$, $$markus.feldmann@giz.de$$, (SELECT id FROM organizations WHERE name = $$GIZ$$), 2014, 2024, $$Digital governance projects in Eastern Europe and Africa$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Lena has worked in my section for ten years. She led our open data work in Ukraine and the digital identity framework in Rwanda, and both are still running. She combines real technical depth with a policy instinct for what governments will sustain. She is also a generous mentor to younger advisors. I would work with her again on any digital governance project.$$, $$auto$$, '2026-09-01T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-30T16:49:08.421Z'::timestamptz, '2026-09-01T16:34:44.421Z'::timestamptz, '2026-09-01T16:41:56.421Z'::timestamptz, '2026-09-01T16:49:08.421Z'::timestamptz, '2026-09-01T16:49:08.421Z'::timestamptz, '2026-09-02T16:49:08.421Z'::timestamptz, $$0bbd008dcb59e367ba1d8d9f1b322fdf$$, '2026-08-29T16:49:08.421Z'::timestamptz);
