INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('68cd1bfb-81d2-5e19-8034-8b8b36964b8a', '0b3dca45-f309-4196-b83d-8840e915a177', $$d7147573-e066-403d-8556-5e6a5844e4b8$$, NULL, $$Sophie Laurent$$, $$European Union$$, $$Head of Unit, eGovernment$$, $$supervisor$$, $$sophie.laurent@ec.europa.eu$$, (SELECT id FROM organizations WHERE name = $$European Union$$), 2010, 2014, $$eGovernment policy at DG CONNECT$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Lena when she worked on eGovernment policy with us. She brought a technologist's understanding to policy discussions and helped us design support to neighbourhood countries, including the Moldova open budget portal. She is precise, energetic and easy to work with. I would gladly work with her again.$$, $$auto$$, '2025-12-27T16:49:08.421Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2025-12-25T16:49:08.421Z'::timestamptz, '2025-12-27T16:34:44.421Z'::timestamptz, '2025-12-27T16:41:56.421Z'::timestamptz, '2025-12-27T16:49:08.421Z'::timestamptz, '2025-12-27T16:49:08.421Z'::timestamptz, '2025-12-28T16:49:08.421Z'::timestamptz, $$578fcb98d147ed290a62b51fdbdd6966$$, '2025-12-24T16:49:08.421Z'::timestamptz);
