INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('cc6168b5-8239-5c5f-bfd5-df14d4b34336', '0b3dca45-f309-4196-b83d-8840e915a177', NULL, '468429de-1279-53d2-b0f6-be96753ccde7', $$Aziz Karimov$$, $$World Bank$$, $$Digital Development Specialist$$, $$client$$, $$akarimov@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2023, 2024, $$Digital public infrastructure roadmap for Uzbekistan$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I worked alongside Lena on Uzbekistan's digital public infrastructure roadmap, which GIZ led and we co-financed. She kept a complex group of ministries focused on a phased plan instead of a wish list. The data exchange priority she argued for is now in the budget. I would work with her again on DPI assignments.$$, $$auto$$, NULL, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-09-11T16:49:08.421Z'::timestamptz, '2026-09-13T16:34:44.421Z'::timestamptz, '2026-09-13T16:41:56.421Z'::timestamptz, '2026-09-13T16:49:08.421Z'::timestamptz, '2026-09-13T16:49:08.421Z'::timestamptz, '2026-09-14T16:49:08.421Z'::timestamptz, $$abff15c522c3f1ed9a1a71ef7942383e$$, '2026-09-10T16:49:08.421Z'::timestamptz);
