  ('9e205d54-c875-5123-83e9-05013ca6b816', 'cc6168b5-8239-5c5f-bfd5-df14d4b34336', 'code_confirmed', 'referee', '{"demo": true}'::jsonb, '2026-09-13T16:34:44.421Z'::timestamptz),
  ('7b5f3d40-51e6-5c71-a4b9-2c068dd44f09', 'cc6168b5-8239-5c5f-bfd5-df14d4b34336', 'details_accepted', 'referee', '{"demo": true}'::jsonb, '2026-09-13T16:41:56.421Z'::timestamptz),
