  ('b87994c1-30bd-5264-9568-e00626eb265f', 'cc6168b5-8239-5c5f-bfd5-df14d4b34336', 'recording_submitted', 'referee', '{"demo": true}'::jsonb, '2026-09-13T16:49:08.421Z'::timestamptz),
