  ('abc9769d-80d5-5ca3-a0a6-4fc5996ddcad', '0b3dca45-f309-4196-b83d-8840e915a177', 'degree', $$1b8412e8-ef0f-48eb-ad22-0c6403eb1d9d$$, $$Master of Public Policy, Hertie School, 2011–2013$$, '9756c004', 'confirmed', 'degree_service', $${"note":"Demo: confirmed by degree-verification service (placeholder)."}$$::jsonb, 'admin', $$Demo Admin$$, '2025-12-02T19:49:08.421Z'::timestamptz);

-- Tariq Hassan
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('bda892da-0191-40bf-ac28-2469d1ef7613', 'b48d9270-658b-41e4-b211-0387a4a9cff1', $$Amman Bus Rapid Transit Pre-Feasibility Study, Jordan$$, $$Islamic Development Bank$$, (SELECT id FROM organizations WHERE name = $$Islamic Development Bank$$), 2017, 2018, $$Lead Transport Economist$$, $$Led the economic and financial analysis for a proposed BRT corridor in Amman, including ridership modelling, cost-benefit analysis, and carbon emissions assessment, informing a $180M investment decision by the Islamic Development Bank.$$, $$Pre-feasibility established the economic case for two priority BRT corridors; the study's demand model and phasing plan were carried into the subsequent detailed design procurement.$$, $$[{"url":"https://picsum.photos/seed/tariq-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/tariq-portfolio-1-img1/900/600","caption":"Corridor traffic survey, Amman"},{"url":"https://picsum.photos/seed/tariq-portfolio-1-img2/900/600","caption":"Stakeholder review of proposed BRT alignment"}]$$::jsonb, $$[{"url":"https://example.org/amman-brt","label":"Project brief"}]$$::jsonb, NULL, 1),
  ('e03193a4-2bbe-4bf7-bfbc-ecf0907b1f7a', 'b48d9270-658b-41e4-b211-0387a4a9cff1', $$Road Safety Investment Program, AfDB, Morocco & Tunisia$$, $$African Development Bank$$, (SELECT id FROM organizations WHERE name = $$African Development Bank$$), 2020, 2022, $$Infrastructure Specialist$$, $$Designed a $45M African Development Bank road safety program across Morocco and Tunisia, including black-spot identification using crash data analytics, engineering countermeasure design, and institutional reform support for road agencies.$$, $$Program identified high-fatality corridors and a costed safety-upgrade package; AfDB approved financing for the first tranche of black-spot interventions.$$, $$[{"url":"https://picsum.photos/seed/tariq-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/tariq-portfolio-2-img1/900/600","caption":"Black-spot road-safety audit"}]$$::jsonb, $$[{"url":"https://www.afdb.org/en/topics-and-sectors/sectors/transport","label":"AfDB transport"}]$$::jsonb, NULL, 2),
  ('52b129a4-5151-4977-a17f-3ade83e07b69', 'b48d9270-658b-41e4-b211-0387a4a9cff1', $$National Transport Strategy, Republic of Lebanon$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2021, 2022, $$Transport Policy Advisor$$, $$Contributed to Lebanon's 2022 National Transport Strategy, developing the urban mobility and freight logistics components and facilitating multi-stakeholder workshops with the Ministry of Public Works and Transport.$$, $$Strategy provided the first integrated multimodal transport vision in over a decade; adopted as the reference framework for donor coordination on transport investment.$$, $$[{"url":"https://picsum.photos/seed/tariq-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/tariq-portfolio-3-img1/900/600","caption":"Multimodal planning workshop, Beirut"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
