INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('2b12ec2d-c3b1-4a80-96a5-558becf40d35', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', $$Sovereign Green Bond Framework, Royal Government of Thailand$$, $$ADB$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2019, 2020, $$Lead Climate Finance Advisor$$, $$Developed Thailand's inaugural sovereign green bond framework — the first in ASEAN to include a social co-benefits framework — enabling the Ministry of Finance to issue $1.5B in green bonds aligned with the ASEAN Green Bond Standards.$$, $$Framework underpinned a benchmark sovereign green-bond issuance; received a Second Party Opinion aligning it with ICMA Green Bond Principles and set the template for subsequent issuances.$$, $$[{"url":"https://picsum.photos/seed/mei-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/mei-portfolio-1-img1/900/600","caption":"Green-bond framework launch event"},{"url":"https://picsum.photos/seed/mei-portfolio-1-img2/900/600","caption":"Eligible-project taxonomy workshop"}]$$::jsonb, $$[{"url":"https://www.icmagroup.org/sustainable-finance/the-principles-guidelines-and-handbooks/green-bond-principles-gbp/","label":"ICMA Green Bond Principles"},{"url":"https://example.org/thailand-green-bond","label":"Framework summary"}]$$::jsonb, NULL, 1),
  ('30a612e4-3ee5-4a9f-b3be-d569770f9919', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', $$GCF Readiness Program, Government of Cambodia$$, $$ADB$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2021, 2022, $$GCF Access Specialist$$, $$Supported Cambodia's National Designated Authority to develop its GCF country programming strategy and accreditation roadmap, resulting in two projects approved for GCF pipeline consideration.$$, $$Readiness support secured Cambodia's accreditation pathway to the Green Climate Fund and produced a pipeline of three concept notes, one of which advanced to full funding proposal.$$, $$[{"url":"https://picsum.photos/seed/mei-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/mei-portfolio-2-img1/900/600","caption":"GCF readiness planning session, Phnom Penh"}]$$::jsonb, $$[{"url":"https://www.greenclimate.fund/","label":"Green Climate Fund"}]$$::jsonb, NULL, 2),
  ('5941c891-9a8d-41da-8f6f-9ce37841d33e', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', $$Carbon Credit Methodology for Off-Grid Solar, Mekong Region$$, $$IFC$$, (SELECT id FROM organizations WHERE name = $$International Finance Corporation$$), 2016, 2017, $$Carbon Markets Specialist$$, $$Designed a Verra-verified carbon credit methodology for off-grid solar home systems across Laos, Myanmar, and Cambodia, establishing the monitoring, reporting, and verification framework for a 500,000-tonne CO2e credit stream.$$, $$Methodology enabled off-grid solar providers to access voluntary carbon revenue; validated approach was applied across an initial portfolio of 15,000 household systems.$$, $$[{"url":"https://picsum.photos/seed/mei-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/mei-portfolio-3-img1/900/600","caption":"Off-grid solar installation, rural Mekong"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('f14f6b13-59d2-5f9c-936f-4edc753e6878', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', $$Blended Finance Facility for Industrial Energy Efficiency, Viet Nam$$, $$International Finance Corporation$$, (SELECT id FROM organizations WHERE name = $$International Finance Corporation$$), 2017, 2018, $$Climate Business Analyst$$, $$Structured a blended finance facility pairing concessional climate funds with local bank lending for energy efficiency upgrades in textile and food processing factories, including the ESG reporting requirements for participating banks.$$, $$Three local banks joined; USD 85 million in loans committed in the first two years.$$, $$[{"url":"https://picsum.photos/seed/mei-ling-chen-blended-finance-facility-for-industrial--1/900/600","caption":"Factory energy audit"},{"url":"https://picsum.photos/seed/mei-ling-chen-blended-finance-facility-for-industrial--2/900/600","caption":"Bank training on ESG reporting"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('df638e04-3211-5c77-8d6e-53fdd154be19', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', $$020c1d3c-b781-41b6-bacc-05f9a7fedcd7$$, NULL, $$Daniel Lim$$, $$Asian Development Bank$$, $$Principal Climate Change Specialist$$, $$supervisor$$, $$dlim@adb.org$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2018, 2023, $$Climate finance operations in Southeast Asia$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Mei-Ling worked in my team for five years. She led the technical work on Thailand's sovereign green bond framework and the GCF readiness programme in Cambodia. She understands both finance and climate policy, and she is excellent with ministry counterparts. I would work with her again on green bonds, climate funds or carbon markets.$$, $$auto$$, '2026-07-25T16:49:08.421Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-23T16:49:08.421Z'::timestamptz, '2026-07-25T16:34:44.421Z'::timestamptz, '2026-07-25T16:41:56.421Z'::timestamptz, '2026-07-25T16:49:08.421Z'::timestamptz, '2026-07-25T16:49:08.421Z'::timestamptz, '2026-07-26T16:49:08.421Z'::timestamptz, $$4d3b405f350a8ec849e3b10c829c671f$$, '2026-07-22T16:49:08.421Z'::timestamptz);
