INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('a2ffb80c-a037-51b7-929f-bb4a7071d6bf', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', $$002d2893-613b-4b38-a904-d4505089e912$$, NULL, $$Priscilla Wong$$, $$International Finance Corporation$$, $$Senior Investment Officer, Climate Business$$, $$supervisor$$, $$pwong@ifc.org$$, (SELECT id FROM organizations WHERE name = $$International Finance Corporation$$), 2015, 2018, $$Climate business in the Mekong region$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Mei-Ling at IFC. She built our carbon credit methodology for off-grid solar and the blended finance facility for energy efficiency in Viet Nam. She is analytical, fast and very good at explaining complex structures to bankers. I would gladly work with her again.$$, $$auto$$, '2025-12-07T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2025-12-05T16:49:08.421Z'::timestamptz, '2025-12-07T16:34:44.421Z'::timestamptz, '2025-12-07T16:41:56.421Z'::timestamptz, '2025-12-07T16:49:08.421Z'::timestamptz, '2025-12-07T16:49:08.421Z'::timestamptz, '2025-12-08T16:49:08.421Z'::timestamptz, $$bf1c068759a69b821f8fe85e0f7eeb9e$$, '2025-12-04T16:49:08.421Z'::timestamptz);
