INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('a5fca5d9-804a-5105-b600-b10e3d48fb9a', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of Thailand's sovereign green bond framework. I led the technical work on eligible projects and reporting. What changed is that the government raised its first green bond and now reports allocation and impact every year.$$, 20),
  ('a0f1f222-28ce-5588-9d3b-5d2f7d01cf5b', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Cambodia I had to learn a new institutional context quickly for the GCF readiness programme. I mapped who really decided on climate finance, and I made sure the national designated authority led every step.$$, 20),
  ('592469b0-69eb-5d85-869c-b6a6f8e7f2d9', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] When a carbon methodology we had developed failed an external review, I told the client immediately, explained what we had missed, and proposed a revised approach with the reviewer's comments addressed.$$, 20),
  ('e8a392ae-12fa-5886-9e44-d310ea5a1f38', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in English, Thai and Mandarin, and I prefer to co-design with local banks and ministries. They know which products their clients will actually take up.$$, 20),
  ('abbe0781-7904-51fa-9d8a-15216532aad2', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in green bond frameworks. They are not the right tool for small borrowers or projects with no clear revenue; there, results-based grants or credit lines work better.$$, 20);
INSERT INTO verification_checks (id, profile_id, item_kind, item_id, item_summary, item_fingerprint, outcome, method, detail, actor, actor_name, created_at) VALUES
