  ('f32e94ac-bf6c-597b-9c62-a0c4365f254e', 'e1ff6a4f-a52d-46a9-b498-52d6f3659bdc', 'identity', $$identity$$, $$Mei-Ling Chen$$, '569b2c21', 'confirmed', 'id_provider', $${"note":"Photo matches the ID check."}$$::jsonb, 'admin', $$Demo Admin$$, '2025-11-12T18:49:08.421Z'::timestamptz),
