INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('957117ce-09a8-4dda-be42-f06c70a926f9', '382822da-2b19-45d6-8c2f-6296957fcdc4', $$Climate Vulnerability Assessment, Bangladesh Delta Region$$, $$UNICEF Bangladesh$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2022, 2023, $$Lead Technical Specialist$$, $$Conducted a comprehensive climate vulnerability and risk assessment for WASH infrastructure across 14 coastal upazilas in Bangladesh, integrating sea-level rise projections, cyclone track modelling, and groundwater salinity data to prioritize a $120M adaptation investment plan.$$, $$Assessment mapped salinity and flood exposure for 2M+ delta residents; results fed directly into the World Bank's delta-resilience investment prioritization.$$, $$[{"url":"https://picsum.photos/seed/rohan-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/rohan-portfolio-1-img1/900/600","caption":"Salinity monitoring, coastal Bangladesh"},{"url":"https://picsum.photos/seed/rohan-portfolio-1-img2/900/600","caption":"Community vulnerability-mapping session"}]$$::jsonb, $$[{"url":"https://www.worldbank.org/en/country/bangladesh","label":"World Bank Bangladesh"},{"url":"https://example.org/bangladesh-delta-vulnerability","label":"Assessment summary"}]$$::jsonb, NULL, 1),
  ('46eae959-a949-4fd2-96f9-8a3cfdff5815', '382822da-2b19-45d6-8c2f-6296957fcdc4', $$Cyclone-Resilient Water Supply Design, Odisha State, India$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2019, 2021, $$WASH Infrastructure Specialist$$, $$Led engineering design of elevated and flood-proofed community water supply systems in 120 coastal villages in Odisha, incorporating community water safety plans and climate stress-testing protocols.$$, $$Resilient water-supply designs deployed in cyclone-exposed coastal blocks; systems maintained safe-water access through a subsequent severe-storm season.$$, $$[{"url":"https://picsum.photos/seed/rohan-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/rohan-portfolio-2-img1/900/600","caption":"Elevated water-supply infrastructure, coastal Odisha"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('034c242c-9b5f-490c-80a2-70fe73aca7d6', '382822da-2b19-45d6-8c2f-6296957fcdc4', $$Urban Sanitation Resilience Plan, Dhaka North City Corporation$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2021, 2022, $$Climate Resilience Advisor$$, $$Developed Dhaka North's urban sanitation climate resilience plan, identifying infrastructure at risk from riverine flooding and developing a phased adaptation investment programme with the city's WASH utility.$$, $$Plan established a flood-resilient sanitation strategy for a rapidly growing urban area; prioritized investments were incorporated into the city corporation's capital plan.$$, $$[{"url":"https://picsum.photos/seed/rohan-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/rohan-portfolio-3-img1/900/600","caption":"Drainage and sanitation survey, Dhaka North"}]$$::jsonb, $$[{"url":"https://example.org/dhaka-sanitation-resilience","label":"Plan overview"}]$$::jsonb, NULL, 3);
