-- Fatmata Kamara
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('1d503e9c-cf2e-44c9-b98e-4554de52ec99', 'da0913e7-f927-5b24-bd8a-2d447aac7d81', $$Farmer Field School Outcome Survey, Bombali$$, $$FAO Sierra Leone$$, (SELECT id FROM organizations WHERE name = $$FAO$$), 2023, 2023, $$Survey Coordinator$$, $$Designed and coordinated a tablet-based survey of 600 farmer field school members on adoption of improved rice practices.$$, $$Survey showed 40% adoption of line planting and informed the next season's training plan.$$, $$[{"url":"https://picsum.photos/seed/demo-fatmata-kamara-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-fatmata-kamara-portfolio-1-img1/900/600","caption":"Farmer field school session in Bombali"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('9a2299a2-6008-48f8-8b2e-01f7094826ec', 'da0913e7-f927-5b24-bd8a-2d447aac7d81', $$Upland Land-Use Mapping Study$$, $$Sierra Leone Agricultural Research Institute$$, NULL, 2022, 2023, $$GIS Assistant$$, $$Mapped 900 upland plots with GPS and QGIS to measure fallow periods and slash-and-burn clearing.$$, $$Maps used to target agroecology demonstration sites.$$, $$[{"url":"https://picsum.photos/seed/demo-fatmata-kamara-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-fatmata-kamara-portfolio-2-img1/900/600","caption":"Plot boundary mapping with a farmer"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('895954f7-024a-5453-8306-9a674dca4200', 'da0913e7-f927-5b24-bd8a-2d447aac7d81', $$Rice Variety Demonstration Plots and Extension Messages, Kambia$$, $$IFAD$$, (SELECT id FROM organizations WHERE name = $$IFAD$$), 2024, 2025, $$Research Officer$$, $$Set up demonstration plots for three drought-tolerant rice varieties with women's farmer groups, recorded yields and labour, and turned the results into simple extension messages and radio scripts in Krio and Temne.$$, $$Adoption of the best-performing variety by 40% of participating farmers in the following season.$$, $$[{"url":"https://picsum.photos/seed/demo-fatmata-kamara-rice-variety-demonstration-plots-and-ext-1/900/600","caption":"Demonstration plot with a women's farmer group"},{"url":"https://picsum.photos/seed/demo-fatmata-kamara-rice-variety-demonstration-plots-and-ext-2/900/600","caption":"Recording a radio extension message"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('48fff0a3-cbf4-5089-9e96-4aabc672d1ff', 'da0913e7-f927-5b24-bd8a-2d447aac7d81', $$eace50b3-b913-4d47-a34a-2834be1cc375$$, NULL, $$Mohamed Sesay$$, $$Welthungerhilfe$$, $$Programme Manager$$, $$supervisor$$, $$mohamed.sesay@welthungerhilfe.de$$, (SELECT id FROM organizations WHERE name = $$Welthungerhilfe$$), 2020, 2022, $$Farmer field schools and household surveys in Bombali$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Fatmata worked with me as a field assistant for two years. She organised farmer field school surveys across thirty villages and her data were always complete and on time. Farmers trusted her, especially women, and she was careful to explain why we were asking questions. She has grown a lot since then. I would work with her again on agricultural research and surveys.$$, $$auto$$, '2026-07-05T16:49:08.421Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-03T16:49:08.421Z'::timestamptz, '2026-07-05T16:34:44.421Z'::timestamptz, '2026-07-05T16:41:56.421Z'::timestamptz, '2026-07-05T16:49:08.421Z'::timestamptz, '2026-07-05T16:49:08.421Z'::timestamptz, '2026-07-06T16:49:08.421Z'::timestamptz, $$f4e2553b90cf7a9a15a43a11b4df1591$$, '2026-07-02T16:49:08.421Z'::timestamptz);
