-- Aisha Bello Danjuma
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('763b79d6-d0af-416d-8a43-1d3e5d6e9ced', '44e07947-c847-5be7-a38c-04e1acb6057b', $$Early Grade Reading Curriculum in Hausa, Kano and Katsina$$, $$FCDO$$, (SELECT id FROM organizations WHERE name = $$FCDO$$), 2018, 2021, $$Curriculum Lead$$, $$Designed scripted lessons and teacher guides for early grade reading in Hausa and led the training of trainers cascade for 4,800 teachers.$$, $$Oral reading fluency in pilot schools doubled over two years; the curriculum was adopted statewide.$$, $$[{"url":"https://picsum.photos/seed/demo-aisha-bello-danjuma-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-aisha-bello-danjuma-portfolio-1-img1/900/600","caption":"Teacher training session in Kano"},{"url":"https://picsum.photos/seed/demo-aisha-bello-danjuma-portfolio-1-img2/900/600","caption":"Hausa reading lesson in Primary 2"}]$$::jsonb, $$[{"url":"https://example.org/hausa-early-grade-reading","label":"Programme summary"}]$$::jsonb, NULL, 1),
  ('020b84b5-7dc3-414a-a234-4c1f0827a94c', '44e07947-c847-5be7-a38c-04e1acb6057b', $$Radio and E-Learning Lessons During School Closures$$, $$UNICEF Nigeria$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2020, 2021, $$Content Lead$$, $$Led production of radio lessons and e-learning modules for primary learners in Hausa and English, with guidance for caregivers.$$, $$Lessons broadcast on four state radio stations and reached an estimated 900,000 children.$$, $$[{"url":"https://picsum.photos/seed/demo-aisha-bello-danjuma-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-aisha-bello-danjuma-portfolio-2-img1/900/600","caption":"Radio lesson recording"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('8427fd83-9899-5441-9956-e864f1ff6f07', '44e07947-c847-5be7-a38c-04e1acb6057b', $$Girls' Enrolment Community Campaign, Katsina$$, $$UNICEF$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2022, 2023, $$Campaign Lead$$, $$Designed and led a community campaign with traditional and religious leaders, school-based management committees and mothers' associations to enrol and keep girls in primary school, with radio drama in Hausa and household visits.$$, $$Girls' enrolment in participating schools rose by 18%; dropout in Primary 4–6 fell by a third.$$, $$[{"url":"https://picsum.photos/seed/demo-aisha-bello-danjuma-girls-enrolment-community-campaign-katsi-1/900/600","caption":"Mothers' association meeting"},{"url":"https://picsum.photos/seed/demo-aisha-bello-danjuma-girls-enrolment-community-campaign-katsi-2/900/600","caption":"Radio drama recording in Hausa"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('a0240de9-a9d8-5e5e-8cec-3e2bc6f05e30', '44e07947-c847-5be7-a38c-04e1acb6057b', $$Pre-Primary Teacher Guide in Hausa$$, $$Kano State Universal Basic Education Board$$, NULL, 2015, 2016, $$Director of Teacher Development$$, $$Led the writing of a play-based pre-primary teacher guide in Hausa and the training of 600 caregivers in early childhood centres attached to primary schools.$$, $$Guide adopted for all public pre-primary classes in Kano State.$$, $$[{"url":"https://picsum.photos/seed/demo-aisha-bello-danjuma-pre-primary-teacher-guide-in-hausa-1/900/600","caption":"Caregiver training session"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('697ab5f3-a0e6-5a2e-ba2a-337cbbdffcf7', '44e07947-c847-5be7-a38c-04e1acb6057b', $$229c6a6e-e78b-482a-92af-095f7b224dd2$$, NULL, $$Hauwa Abdullahi$$, $$UNICEF$$, $$Education Specialist$$, $$supervisor$$, $$h.abdullahi@unicef.org$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2010, 2017, $$Teacher development at the Kano State Universal Basic Education Board$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I was Aisha's director at the Kano State Universal Basic Education Board before I joined UNICEF. She built our teacher development system almost from scratch and trained hundreds of teachers herself. She understands classrooms in northern Nigeria better than anyone I know. I would work with her again on early grade reading, teacher training or girls' education.$$, $$auto$$, '2026-07-30T16:49:08.421Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-28T16:49:08.421Z'::timestamptz, '2026-07-30T16:34:44.421Z'::timestamptz, '2026-07-30T16:41:56.421Z'::timestamptz, '2026-07-30T16:49:08.421Z'::timestamptz, '2026-07-30T16:49:08.421Z'::timestamptz, '2026-07-31T16:49:08.421Z'::timestamptz, $$5d995229fef0ee72150f6ae57a017bcb$$, '2026-07-27T16:49:08.421Z'::timestamptz);
