INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('2f1f6e5a-cf9b-52da-aa09-7966927fe20d', '44e07947-c847-5be7-a38c-04e1acb6057b', NULL, '8427fd83-9899-5441-9956-e864f1ff6f07', $$Ibrahim Musa Garba$$, $$UNICEF$$, $$Social and Behaviour Change Officer$$, $$client$$, $$ibrahim.garba@unicef.org$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2022, 2023, $$Girls' enrolment campaign in Katsina$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We contracted Aisha to lead our girls' enrolment campaign in Katsina. She brought religious leaders and mothers' associations together in a way we had not managed before, and the enrolment figures moved within one school year. Her radio drama scripts were excellent. I would work with her again.$$, $$auto$$, '2026-08-24T16:49:08.421Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-22T16:49:08.421Z'::timestamptz, '2026-08-24T16:34:44.421Z'::timestamptz, '2026-08-24T16:41:56.421Z'::timestamptz, '2026-08-24T16:49:08.421Z'::timestamptz, '2026-08-24T16:49:08.421Z'::timestamptz, '2026-08-25T16:49:08.421Z'::timestamptz, $$548594200f3cabf2c64ce4a4cfb71390$$, '2026-08-21T16:49:08.421Z'::timestamptz);
