INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('bbd0ff39-adfb-52da-9e77-9fcccc48bf34', '44e07947-c847-5be7-a38c-04e1acb6057b', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the early grade reading curriculum in Hausa. I led the writing team and the training cascade. What changed is that children in Kano and Katsina now learn to read in the language they speak at home, and reading scores rose in the first evaluation.$$, 20),
  ('107e6e1e-4fda-5bfb-9d9d-f7d8b911606a', '44e07947-c847-5be7-a38c-04e1acb6057b', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] When I worked on radio lessons during school closures, I had to deliver in a context nobody knew: education with no classrooms. We tested scripts with families in two villages before recording anything, and that saved us from many mistakes.$$, 20),
  ('c0d416aa-7873-5ecd-80f1-810b22ed139e', '44e07947-c847-5be7-a38c-04e1acb6057b', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] Once a midline assessment showed weak results in one state. I told the funder plainly, explained that teachers had received materials late, and proposed a catch-up plan that we delivered before the endline.$$, 20),
  ('a24b6ef9-724d-5d25-8049-447285a21503', '44e07947-c847-5be7-a38c-04e1acb6057b', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] In northern Nigeria nothing works without community leaders. I always start with traditional and religious leaders and mothers' associations, and I work in Hausa so that everyone can follow.$$, 20),
  ('2352cb82-28b6-5cd2-947d-71c0fb3107ae', '44e07947-c847-5be7-a38c-04e1acb6057b', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in structured pedagogy. It is not the right tool for very small multigrade schools where one teacher has six grades; there, simpler self-paced materials work better.$$, 20);
