-- Chidi Okonkwo-Nwosu
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('d6ab2372-1469-4e7c-b879-2e1adfe04a55', '6ab3688d-135d-5f89-b4f8-32ba25129b2a', $$Innovation Hub Strategy, Enugu State$$, $$GIZ Nigeria$$, (SELECT id FROM organizations WHERE name = $$GIZ$$), 2021, 2022, $$Lead Consultant$$, $$Mapped the state's start-up ecosystem and designed the operating model for a public-private innovation hub.$$, $$Hub opened in 2023 and supported 60 start-ups in its first year.$$, $$[{"url":"https://picsum.photos/seed/demo-chidi-okonkwo-nwosu-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-chidi-okonkwo-nwosu-portfolio-1-img1/900/600","caption":"Ecosystem mapping workshop in Enugu"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('8a1058ac-bc19-46d6-9f0e-f0b31a79e691', '6ab3688d-135d-5f89-b4f8-32ba25129b2a', $$Youth Entrepreneur Finance Market Study$$, $$Mastercard Foundation$$, (SELECT id FROM organizations WHERE name = $$Mastercard Foundation$$), 2020, 2020, $$Market Research Lead$$, $$Surveyed 1,000 young entrepreneurs and 20 lenders on demand for and supply of SME finance in Lagos, Kano and Port Harcourt.$$, $$Study informed a youth SME lending guarantee programme.$$, $$[{"url":"https://picsum.photos/seed/demo-chidi-okonkwo-nwosu-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-chidi-okonkwo-nwosu-portfolio-2-img1/900/600","caption":"Interview with a young entrepreneur in Yaba"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('e490e91d-7d26-5fbf-aa9f-b73093b4f929', '6ab3688d-135d-5f89-b4f8-32ba25129b2a', $$Angel Investor Network Feasibility Study, South-East Nigeria$$, $$GIZ$$, (SELECT id FROM organizations WHERE name = $$GIZ$$), 2023, 2023, $$Lead Consultant$$, $$Assessed demand and supply for early-stage investment in Enugu, Anambra and Abia, interviewed 40 founders and 25 potential angel investors, and designed a blended first-loss facility to crowd private investors into seed deals.$$, $$Angel network launched with 18 members; first five investments closed within a year.$$, $$[{"url":"https://picsum.photos/seed/demo-chidi-okonkwo-nwosu-angel-investor-network-feasibility-study-1/900/600","caption":"Founder interviews in Enugu"},{"url":"https://picsum.photos/seed/demo-chidi-okonkwo-nwosu-angel-investor-network-feasibility-study-2/900/600","caption":"Investor workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('9410d7e0-e777-579a-9740-f701309126bd', '6ab3688d-135d-5f89-b4f8-32ba25129b2a', $$d81787cd-c05f-4b16-9046-1b650aad13e0$$, NULL, $$Kelechi Nnamdi$$, $$GIZ$$, $$Senior Advisor, Private Sector Development$$, $$supervisor$$, $$kelechi.nnamdi@giz.de$$, (SELECT id FROM organizations WHERE name = $$GIZ$$), 2016, 2020, $$Accelerator programmes at Ventures Platform$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I managed Chidi at Ventures Platform before I joined GIZ. He ran our accelerator cohorts and was the person founders called when things went wrong. He is commercially sharp but also cares about inclusion; he pushed us to recruit more women founders and founders from outside Lagos. I would work with him again on SME and innovation programmes.$$, $$auto$$, '2026-05-26T16:49:08.421Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-05-24T16:49:08.421Z'::timestamptz, '2026-05-26T16:34:44.421Z'::timestamptz, '2026-05-26T16:41:56.421Z'::timestamptz, '2026-05-26T16:49:08.421Z'::timestamptz, '2026-05-26T16:49:08.421Z'::timestamptz, '2026-05-27T16:49:08.421Z'::timestamptz, $$80a3d3912866f1f852c2e8f42c81882c$$, '2026-05-23T16:49:08.421Z'::timestamptz);
