-- Mariam Traoré
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('7266b212-c14c-4317-9396-ad718ec6e342', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', $$Resilience Programme M&E System, Mopti and Ségou$$, $$European Union$$, (SELECT id FROM organizations WHERE name = $$European Union$$), 2019, 2022, $$M&E Lead$$, $$Designed the results framework, household resilience survey and remote monitoring system for a multi-partner resilience programme in conflict-affected areas.$$, $$System tracked 45,000 households; data led to earlier lean-season cash transfers in 2021.$$, $$[{"url":"https://picsum.photos/seed/demo-mariam-traore-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-mariam-traore-portfolio-1-img1/900/600","caption":"Enumerator training in Ségou"},{"url":"https://picsum.photos/seed/demo-mariam-traore-portfolio-1-img2/900/600","caption":"Monitoring visit to a women's market garden"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('6879acc2-f36f-44fa-9f5f-3086a1129261', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', $$Evaluation of Seasonal Cash Transfers, Northern Burkina Faso$$, $$World Food Programme$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2022, 2023, $$Evaluation Team Leader$$, $$Mixed-methods evaluation of lean-season cash transfers to displaced and host households, with a 1,500-household survey and statistical analysis of food consumption scores.$$, $$Evaluation recommended transfer-value indexing to market prices, adopted for the 2024 lean season.$$, $$[{"url":"https://picsum.photos/seed/demo-mariam-traore-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-mariam-traore-portfolio-2-img1/900/600","caption":"Distribution site in Kaya"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('1051e947-ca1a-54c3-8b4d-61b418932bef', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', $$Early Warning Indicator Review, Mali$$, $$European Union$$, (SELECT id FROM organizations WHERE name = $$European Union$$), 2018, 2018, $$Lead Consultant$$, $$Reviewed the indicators and data flows of Mali's national early warning system against Cadre Harmonisé requirements and recommended changes to market, rainfall and pastoral indicators.$$, $$Five new pastoral indicators adopted; regional bulletins published two weeks earlier.$$, $$[{"url":"https://picsum.photos/seed/demo-mariam-traore-early-warning-indicator-review-mali-1/900/600","caption":"Data review with early warning analysts"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('bce5c69d-7e95-57d5-97a5-16ac7e8a49ae', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', $$Pastoral Resilience Baseline, Tillabéri and Tahoua$$, $$FAO$$, (SELECT id FROM organizations WHERE name = $$FAO$$), 2021, 2021, $$Survey Lead$$, $$Designed and led the baseline survey for a pastoral resilience programme covering herd size, animal health access, mobility and household food security in two regions of Niger.$$, $$Baseline used to set targets for animal health and fodder components.$$, $$[{"url":"https://picsum.photos/seed/demo-mariam-traore-pastoral-resilience-baseline-tillaberi-a-1/900/600","caption":"Herder interviews near Tahoua"},{"url":"https://picsum.photos/seed/demo-mariam-traore-pastoral-resilience-baseline-tillaberi-a-2/900/600","caption":"Enumerator training"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('2320a458-3a27-5774-ab70-dcf34f34230e', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', $$c4cad02c-455e-4f69-87ed-badd222f3d50$$, NULL, $$Oumar Coulibaly$$, $$World Food Programme$$, $$Head of Research, Assessment and Monitoring$$, $$supervisor$$, $$oumar.coulibaly@wfp.org$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2010, 2016, $$Vulnerability analysis and mapping in Mali$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Mariam in WFP Mali's VAM unit for six years. She ran our food security surveys through two crises and never compromised on data quality, even when access was hard. She is a natural teacher for enumerators and national staff. I would work with her again on any food security or M&E assignment in the Sahel.$$, $$auto$$, '2026-06-15T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-13T16:49:08.421Z'::timestamptz, '2026-06-15T16:34:44.421Z'::timestamptz, '2026-06-15T16:41:56.421Z'::timestamptz, '2026-06-15T16:49:08.421Z'::timestamptz, '2026-06-15T16:49:08.421Z'::timestamptz, '2026-06-16T16:49:08.421Z'::timestamptz, $$c7904937b0f6d286063f1dcda021ec03$$, '2026-06-12T16:49:08.421Z'::timestamptz);
