INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('c49d905e-1b2c-520a-bd66-941146f68b3a', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', NULL, '6879acc2-f36f-44fa-9f5f-3086a1129261', $$Aïssata Sawadogo$$, $$World Food Programme$$, $$Programme Policy Officer, Cash-Based Transfers$$, $$client$$, $$aissata.sawadogo@wfp.org$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2022, 2023, $$Evaluation of seasonal cash transfers in northern Burkina Faso$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We commissioned Mariam to evaluate our seasonal cash transfers in northern Burkina Faso. She managed fieldwork in an insecure area with great care for her team, and the evaluation gave us clear evidence on timing and transfer size. We changed the lean season calendar because of her findings.$$, $$auto$$, '2026-08-14T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-12T16:49:08.421Z'::timestamptz, '2026-08-14T16:34:44.421Z'::timestamptz, '2026-08-14T16:41:56.421Z'::timestamptz, '2026-08-14T16:49:08.421Z'::timestamptz, '2026-08-14T16:49:08.421Z'::timestamptz, '2026-08-15T16:49:08.421Z'::timestamptz, $$c9f26ff395e986ecb81adae645fd429f$$, '2026-08-11T16:49:08.421Z'::timestamptz);
