INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('e7774476-4586-53a4-bd43-38c48cb258b7', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the resilience programme M&E system in Mopti and Ségou. I designed it and trained the partners. What changed is that the programme could see which villages were recovering and which were not, and it moved resources accordingly.$$, 20),
  ('ace933ba-1377-5750-b267-4dbd19b1dc5c', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Burkina Faso I evaluated cash transfers in areas I could not visit myself. I built a team of local enumerators, used phone check-ins and set clear safety rules. The context was unfamiliar, but the local team knew it well.$$, 20),
  ('394f5589-8c5a-55a4-ad48-b180b018329a', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] Our evaluation showed that cash arrived too late in the lean season. I presented the finding to the donor with the calendar data and a concrete proposal to move payments earlier, and they adopted it.$$, 20),
  ('452194f3-aaaf-5f06-8008-eba98bf8d371', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in French, Bambara and English. In the Sahel, trust comes from respecting local authorities and working through local organisations, so I always involve them from the start.$$, 20),
  ('3a159de0-ff20-5bf0-b0e6-8948d8128a58', 'a1704511-bb1b-5b3e-970a-a23ca04d6d8d', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in household food security surveys. They are not the right tool when you need to understand why people make choices; then qualitative interviews tell you far more.$$, 20);
