-- Grace Wanjiru Kamau
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('cc6a1a9c-9566-48d2-8824-d5000f6efc0e', 'bcf1b059-1569-5cfd-b134-3f80c6d5f9a7', $$County Climate Change Action Plans, Isiolo and Marsabit$$, $$Kenya Financing Locally-Led Climate Action Program$$, NULL, 2022, 2023, $$Lead Writer$$, $$Drafted county climate action plans with ward-level consultations on drought, water management and livestock.$$, $$Plans adopted by both county assemblies and used to allocate climate resilience grants.$$, $$[{"url":"https://picsum.photos/seed/demo-grace-wanjiru-kamau-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-grace-wanjiru-kamau-portfolio-1-img1/900/600","caption":"Ward consultation in Isiolo"},{"url":"https://picsum.photos/seed/demo-grace-wanjiru-kamau-portfolio-1-img2/900/600","caption":"Water pan visited during consultations"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('16fa2de7-dd53-4aff-a4dd-1cddaf5842f9', 'bcf1b059-1569-5cfd-b134-3f80c6d5f9a7', $$Drought Resilience Policy Brief Series$$, $$IGAD$$, (SELECT id FROM organizations WHERE name = $$IGAD$$), 2019, 2020, $$Author$$, $$Wrote a series of six policy briefs on groundwater, early warning and WASH services in drylands for regional ministers.$$, $$Briefs were used in the regional drought resilience platform's ministerial meeting.$$, $$[{"url":"https://picsum.photos/seed/demo-grace-wanjiru-kamau-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-grace-wanjiru-kamau-portfolio-2-img1/900/600","caption":"Policy brief launch"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('09f404e0-1cc2-5be7-99d5-a4ce3f6b37e4', 'bcf1b059-1569-5cfd-b134-3f80c6d5f9a7', $$Locally-Led Adaptation Learning Notes$$, $$IIED$$, (SELECT id FROM organizations WHERE name = $$IIED$$), 2023, 2024, $$Writer and Editor$$, $$Wrote a series of six learning notes on how Kenyan counties use climate finance for locally-led adaptation, based on interviews with county officials and community climate committees.$$, $$Notes used in county peer-learning events and cited in the national adaptation plan review.$$, $$[{"url":"https://picsum.photos/seed/demo-grace-wanjiru-kamau-locally-led-adaptation-learning-notes-1/900/600","caption":"Interview with a ward climate committee"},{"url":"https://picsum.photos/seed/demo-grace-wanjiru-kamau-locally-led-adaptation-learning-notes-2/900/600","caption":"Learning note cover"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
