-- Aline Uwimana
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('73519f2b-1841-4d52-80c0-c073752d38ca', '78078601-d739-5415-8ed7-42d8100ddf84', $$Blended Courses for TVET Instructors$$, $$Rwanda TVET Board$$, NULL, 2023, 2024, $$Learning Designer$$, $$Designed four blended courses for TVET instructors on teaching methods and digital tools, with e-learning modules on Moodle.$$, $$650 instructors completed the courses; completion rate 82%.$$, $$[{"url":"https://picsum.photos/seed/demo-aline-uwimana-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-aline-uwimana-portfolio-1-img1/900/600","caption":"Instructor workshop in Musanze"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('3bb03600-82e4-4068-b330-e59bfb958b2c', '78078601-d739-5415-8ed7-42d8100ddf84', $$Online Entrepreneurship Module for University Students$$, $$University of Rwanda$$, (SELECT id FROM organizations WHERE name = $$University of Rwanda$$), 2021, 2022, $$Course Designer$$, $$Built an online entrepreneurship module with case studies from Kigali start-ups and a simple web tool for team project submissions.$$, $$Module now compulsory for second-year business students.$$, $$[{"url":"https://picsum.photos/seed/demo-aline-uwimana-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-aline-uwimana-portfolio-2-img1/900/600","caption":"Student pitch session"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('1ae4180d-3fcb-5c35-9f37-e6a51ec22c18', '78078601-d739-5415-8ed7-42d8100ddf84', $$Online Assessment Toolkit for TVET Instructors$$, $$Rwanda TVET Board$$, NULL, 2024, 2025, $$Learning Designer$$, $$Designed a toolkit and short online course to help TVET instructors set practical assessments on Moodle, tested with instructors in three colleges through two rounds of user feedback.$$, $$220 instructors completed the course; practical assessments on Moodle rose from 12% to 55% of modules.$$, $$[{"url":"https://picsum.photos/seed/demo-aline-uwimana-online-assessment-toolkit-for-tvet-instr-1/900/600","caption":"User testing with instructors"},{"url":"https://picsum.photos/seed/demo-aline-uwimana-online-assessment-toolkit-for-tvet-instr-2/900/600","caption":"Course dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
