-- Achieng Otieno
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('302889e6-4514-4803-a1d9-afbb06033db3', 'dd526446-acdd-5e22-b584-551fcd5a84ca', $$Climate and Health Infographic Series$$, $$Africa Population and Health Research Center$$, (SELECT id FROM organizations WHERE name = $$African Population and Health Research Center$$), 2021, 2022, $$Designer$$, $$Designed a series of 20 infographics and a report layout on heat, air quality and child health in Nairobi informal settlements.$$, $$Series shared widely on social media and used in county health briefings.$$, $$[{"url":"https://picsum.photos/seed/demo-achieng-otieno-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-achieng-otieno-portfolio-1-img1/900/600","caption":"Infographic on heat exposure"},{"url":"https://picsum.photos/seed/demo-achieng-otieno-portfolio-1-img2/900/600","caption":"Report spread"}]$$::jsonb, $$[{"url":"https://example.org/achieng-climate-health","label":"Portfolio sample"}]$$::jsonb, NULL, 1),
  ('fa2a5418-8160-4548-8b53-ff07bbe3efcf', 'dd526446-acdd-5e22-b584-551fcd5a84ca', $$Community Health Campaign Identity$$, $$Amref Health Africa$$, (SELECT id FROM organizations WHERE name = $$Amref Health Africa$$), 2023, 2023, $$Brand Designer$$, $$Created the visual identity, posters and short motion graphics for a community health volunteer recruitment campaign.$$, $$Campaign materials used in 12 counties.$$, $$[{"url":"https://picsum.photos/seed/demo-achieng-otieno-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-achieng-otieno-portfolio-2-img1/900/600","caption":"Campaign poster in a health centre"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('39f89063-7279-5a75-8f3b-dc651cd7020c', 'dd526446-acdd-5e22-b584-551fcd5a84ca', $$Menstrual Health Campaign Toolkit$$, $$UNFPA$$, (SELECT id FROM organizations WHERE name = $$UNFPA$$), 2024, 2024, $$Lead Designer$$, $$Designed a campaign toolkit on menstrual health for schools and community health volunteers: posters, a comic for adolescents, social media cards and a facilitator guide, pre-tested with girls and boys in two counties.$$, $$Toolkit used by 300 schools; pre-test feedback led to a boys' version of the comic.$$, $$[{"url":"https://picsum.photos/seed/demo-achieng-otieno-menstrual-health-campaign-toolkit-1/900/600","caption":"Comic pre-test with students"},{"url":"https://picsum.photos/seed/demo-achieng-otieno-menstrual-health-campaign-toolkit-2/900/600","caption":"Poster set"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('cdf4e665-62a8-5ea9-8f79-0553853317c5', 'dd526446-acdd-5e22-b584-551fcd5a84ca', $$57ccb16f-90bf-4699-ab51-53adaf1973a4$$, NULL, $$Dr. Wanjiku Mwangi$$, $$African Population and Health Research Center$$, $$Head of Communications$$, $$supervisor$$, $$w.mwangi@aphrc.org$$, (SELECT id FROM organizations WHERE name = $$African Population and Health Research Center$$), 2020, 2022, $$Design of research publications and infographics$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Achieng was our communications designer for two years. She made complex research readable: her climate and health infographic series reached far beyond our usual audience. She listens to researchers, asks good questions and delivers on time. She also brought real care to how communities are portrayed. I would work with her again on any design for development work.$$, $$auto$$, '2026-07-20T16:49:08.421Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-18T16:49:08.421Z'::timestamptz, '2026-07-20T16:34:44.421Z'::timestamptz, '2026-07-20T16:41:56.421Z'::timestamptz, '2026-07-20T16:49:08.421Z'::timestamptz, '2026-07-20T16:49:08.421Z'::timestamptz, '2026-07-21T16:49:08.421Z'::timestamptz, $$e22a44ec4c1dd3c2b966dcaec9b20e72$$, '2026-07-17T16:49:08.421Z'::timestamptz);
