-- Grâce Mbuyi Tshimanga
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('56d92dff-e2dc-4484-9f27-6710c9e038cc', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', $$Survivors' Access to Justice Study, North and South Kivu$$, $$UN Women$$, (SELECT id FROM organizations WHERE name = $$UN Women$$), 2021, 2022, $$Research Lead$$, $$Led survivor-centred qualitative research with 180 survivors, judges and community leaders on barriers to justice and reparations.$$, $$Findings underpinned a national advocacy campaign and a reparations fund pilot.$$, $$[{"url":"https://picsum.photos/seed/demo-grace-mbuyi-tshimanga-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-grace-mbuyi-tshimanga-portfolio-1-img1/900/600","caption":"Research team training in Goma"},{"url":"https://picsum.photos/seed/demo-grace-mbuyi-tshimanga-portfolio-1-img2/900/600","caption":"Community dialogue in Kalehe"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('ddda61d9-7e78-4e10-b9b5-e29a2cc0cc00', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', $$Evaluation of Community Dialogue Programme, Ituri$$, $$European Union$$, (SELECT id FROM organizations WHERE name = $$European Union$$), 2019, 2019, $$Evaluation Team Leader$$, $$Evaluated a peacebuilding programme using community dialogue and women's mediation networks.$$, $$Evaluation led to expansion of women's mediation networks to two additional territories.$$, $$[{"url":"https://picsum.photos/seed/demo-grace-mbuyi-tshimanga-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-grace-mbuyi-tshimanga-portfolio-2-img1/900/600","caption":"Women's mediation network meeting"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('1f2f94f0-f66b-54b7-9ea3-fbc036f55bd7', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', $$Community Psychosocial Support Model for Survivors, South Kivu$$, $$UNFPA$$, (SELECT id FROM organizations WHERE name = $$UNFPA$$), 2023, 2024, $$Lead Researcher and Designer$$, $$Co-designed a community-based psychosocial support model with survivors' groups and health workers, including referral to specialised mental health care and to legal aid, and tested it in four health zones.$$, $$Model adopted by the provincial GBV sub-cluster; 1,100 survivors supported in the pilot year.$$, $$[{"url":"https://picsum.photos/seed/demo-grace-mbuyi-tshimanga-community-psychosocial-support-model-for-1/900/600","caption":"Survivors' group session"},{"url":"https://picsum.photos/seed/demo-grace-mbuyi-tshimanga-community-psychosocial-support-model-for-2/900/600","caption":"Training of community counsellors"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('20875667-36cf-5df6-b64d-98dd222004d0', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', $$Human Rights Monitoring Training for Women's Organisations, Ituri$$, $$OHCHR$$, (SELECT id FROM organizations WHERE name = $$OHCHR$$), 2020, 2020, $$Trainer$$, $$Trained women's organisations to document human rights violations safely and confidentially, with a simple reporting form and referral protocol.$$, $$25 organisations trained; first quarterly reports submitted to the joint human rights office.$$, $$[{"url":"https://picsum.photos/seed/demo-grace-mbuyi-tshimanga-human-rights-monitoring-training-for-wom-1/900/600","caption":"Training session in Bunia"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('2bcfe592-9e98-5906-82d1-0621d684f5a1', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', $$76ea4420-42f0-4113-bf6e-21cf606aa01b$$, NULL, $$Claudine Mbuyi Kalala$$, $$International Alert$$, $$Country Director$$, $$supervisor$$, $$c.kalala@international-alert.org$$, (SELECT id FROM organizations WHERE name = $$International Alert$$), 2011, 2017, $$Gender and peacebuilding programmes in eastern DRC$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Grâce managed our gender and peacebuilding programme for six years. She is fearless and deeply respectful of survivors, and she built partnerships with women's organisations that still exist. Her research is careful and her advocacy is effective. I would work with her again on GBV, peacebuilding or access to justice.$$, $$auto$$, '2026-06-05T16:49:08.421Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-03T16:49:08.421Z'::timestamptz, '2026-06-05T16:34:44.421Z'::timestamptz, '2026-06-05T16:41:56.421Z'::timestamptz, '2026-06-05T16:49:08.421Z'::timestamptz, '2026-06-05T16:49:08.421Z'::timestamptz, '2026-06-06T16:49:08.421Z'::timestamptz, $$fe5fd6b43488e93842c02f23af050d0e$$, '2026-06-02T16:49:08.421Z'::timestamptz);
