INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('48a62d57-5561-5ca6-9ca7-ae63527546dd', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', NULL, '56d92dff-e2dc-4484-9f27-6710c9e038cc', $$Brigitte Sanzi$$, $$UN Women$$, $$Programme Specialist$$, $$client$$, $$brigitte.sanzi@unwomen.org$$, (SELECT id FROM organizations WHERE name = $$UN Women$$), 2021, 2022, $$Survivors' access to justice study in North and South Kivu$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We commissioned Grâce to lead our study on survivors' access to justice in the Kivus. She designed a safe process with survivors' groups and delivered findings that the justice ministry took seriously. Her recommendations on mobile courts shaped our next programme.$$, $$auto$$, '2026-08-29T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-27T16:49:08.421Z'::timestamptz, '2026-08-29T16:34:44.421Z'::timestamptz, '2026-08-29T16:41:56.421Z'::timestamptz, '2026-08-29T16:49:08.421Z'::timestamptz, '2026-08-29T16:49:08.421Z'::timestamptz, '2026-08-30T16:49:08.421Z'::timestamptz, $$fb87c581064fee5d28904eadd6d356e2$$, '2026-08-26T16:49:08.421Z'::timestamptz);
