INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('4ec98f55-5c55-54a5-b80e-04cadae5882c', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the survivors' access to justice study in North and South Kivu. I led the research with survivors' groups. What changed is that mobile court hearings were scheduled in two territories where survivors had never seen a judge.$$, 20),
  ('a0d3cb6e-eb3a-5821-a69b-d0c616191ab1', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Ituri I worked in a context I knew less well, with different communities and armed groups. I spent time with local women's organisations first and let them guide where and how we worked.$$, 20),
  ('5fbec93c-0479-5eb9-a738-bcd7e5147848', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] When our evaluation found that a community dialogue programme had not reduced tensions, I presented it honestly to the funder, with the reasons and with the parts that did work, so the next phase could build on them.$$, 20),
  ('fc3f340b-b916-5682-8a21-f1ed15a9d2c9', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in French, Swahili, Lingala and English, and I always work with local researchers. In eastern DRC, trust is the most important research method.$$, 20),
  ('516b64cc-a701-5d96-bcf8-88a7628b77c6', '9c516d30-13a6-5c47-a8ec-a90b60c0ba12', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in survivor-centred qualitative research. It is not the right tool when you need prevalence figures for planning; then a carefully designed survey is needed.$$, 20);
