-- Hervé Nkeng Tabi
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('ac948763-2f5e-446a-b320-e9bc02c85b1a', 'ac238e45-6682-5805-8c7e-6425cf64b527', $$Participatory Mapping with Baka Communities, East Region$$, $$Rainforest Foundation UK$$, NULL, 2016, 2018, $$Mapping Coordinator$$, $$Coordinated participatory mapping of customary land use with Baka communities around two national parks.$$, $$Maps of 40 villages submitted to the forestry ministry for recognition of use rights.$$, $$[{"url":"https://picsum.photos/seed/demo-herve-nkeng-tabi-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-herve-nkeng-tabi-portfolio-1-img1/900/600","caption":"Community mapping session"},{"url":"https://picsum.photos/seed/demo-herve-nkeng-tabi-portfolio-1-img2/900/600","caption":"GPS training with Baka mappers"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('399fee64-0fec-4c8d-8fa6-6c4d75f57145', 'ac238e45-6682-5805-8c7e-6425cf64b527', $$Deforestation Risk Mapping for Cocoa Supply Chains$$, $$WWF Cameroon$$, (SELECT id FROM organizations WHERE name = $$WWF$$), 2021, 2022, $$GIS Analyst$$, $$Mapped deforestation risk around cocoa-growing areas to guide sustainable farming support and buyer due diligence.$$, $$Risk maps used by two cocoa exporters for supplier monitoring.$$, $$[{"url":"https://picsum.photos/seed/demo-herve-nkeng-tabi-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-herve-nkeng-tabi-portfolio-2-img1/900/600","caption":"Forest cover change map"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('bac79d2a-0951-566b-88fa-d6037aa88268', 'ac238e45-6682-5805-8c7e-6425cf64b527', $$Free, Prior and Informed Consent Review for a Protected Area Extension$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2023, 2023, $$Safeguards and Mapping Consultant$$, $$Reviewed the consent process with Baka and Bantu communities for the extension of a protected area, mapped customary land use against the proposed boundary, and drafted the process framework for restrictions on access.$$, $$Boundary revised to exclude two customary use areas; process framework approved.$$, $$[{"url":"https://picsum.photos/seed/demo-herve-nkeng-tabi-free-prior-and-informed-consent-review-f-1/900/600","caption":"Customary land-use mapping session"},{"url":"https://picsum.photos/seed/demo-herve-nkeng-tabi-free-prior-and-informed-consent-review-f-2/900/600","caption":"Community consultation"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6a3435f6-38bd-517d-9920-041dd6cbb990', 'ac238e45-6682-5805-8c7e-6425cf64b527', $$b71f0272-5326-449e-8557-47588a9dcfc1$$, NULL, $$Dr. Paul Ngeh$$, $$WWF$$, $$Conservation Director$$, $$supervisor$$, $$pngeh@panda.org$$, (SELECT id FROM organizations WHERE name = $$WWF$$), 2018, 2024, $$Biodiversity mapping and community forestry in Cameroon$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Hervé was our GIS and biodiversity officer for six years. His deforestation risk maps for cocoa supply chains were used by companies and government alike. He is meticulous with data and respectful with communities, especially the Baka. I would work with him again on forest mapping, land use or safeguards work.$$, $$auto$$, '2026-06-20T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-18T16:49:08.421Z'::timestamptz, '2026-06-20T16:34:44.421Z'::timestamptz, '2026-06-20T16:41:56.421Z'::timestamptz, '2026-06-20T16:49:08.421Z'::timestamptz, '2026-06-20T16:49:08.421Z'::timestamptz, '2026-06-21T16:49:08.421Z'::timestamptz, $$4c97653e31d4216efd74b4db087568e1$$, '2026-06-17T16:49:08.421Z'::timestamptz);
