-- Achta Mahamat Saleh
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('759590db-9c2c-4569-8c10-3941e9e5d618', '320b21bb-03d8-5bd1-b545-bd898ce9f2a0', $$Multi-Sector Needs Assessment, Ouaddaï Refugee Camps$$, $$REACH Initiative$$, (SELECT id FROM organizations WHERE name = $$REACH Initiative$$), 2023, 2024, $$Field Supervisor$$, $$Supervised 30 enumerators conducting household surveys on food security, shelter and protection among newly arrived Sudanese refugees.$$, $$Assessment covered 4,200 households and guided the 2024 response plan.$$, $$[{"url":"https://picsum.photos/seed/demo-achta-mahamat-saleh-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-achta-mahamat-saleh-portfolio-1-img1/900/600","caption":"Enumerator briefing in Adré"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('4f7bab20-4312-429b-a34a-8940a03e7ce6', '320b21bb-03d8-5bd1-b545-bd898ce9f2a0', $$Food Security Monitoring in Host Villages$$, $$World Food Programme$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2022, 2022, $$Enumerator Team Lead$$, $$Led data collection for quarterly food security monitoring in host villages near the camps.$$, $$Data informed inclusion of host households in food assistance.$$, $$[{"url":"https://picsum.photos/seed/demo-achta-mahamat-saleh-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-achta-mahamat-saleh-portfolio-2-img1/900/600","caption":"Interview in a host village"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('1eac8869-8aae-54dc-b744-f9eb79f25d1d', '320b21bb-03d8-5bd1-b545-bd898ce9f2a0', $$Shelter and Child Protection Assessment, Farchana Camp$$, $$UNHCR$$, (SELECT id FROM organizations WHERE name = $$UNHCR$$), 2024, 2024, $$Assessment Supervisor$$, $$Supervised a combined shelter and child protection assessment in Farchana camp after the 2023 influx: shelter condition, overcrowding, unaccompanied children and access to child-friendly spaces, with interviews in Arabic and Masalit through interpreters.$$, $$Findings used to prioritise 1,200 transitional shelters and two new child-friendly spaces.$$, $$[{"url":"https://picsum.photos/seed/demo-achta-mahamat-saleh-shelter-and-child-protection-assessment--1/900/600","caption":"Shelter survey in Farchana"},{"url":"https://picsum.photos/seed/demo-achta-mahamat-saleh-shelter-and-child-protection-assessment--2/900/600","caption":"Child-friendly space visit"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
