-- Edvânia Kiala
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('d86d1dc4-1795-4305-8ea5-aadae590b312', 'edbe8a19-f5df-5783-9eb3-271e5edb711d', $$Value-for-Money Review of a Water PPP, Benguela$$, $$Ministério das Finanças de Angola$$, NULL, 2022, 2023, $$Financial Analyst$$, $$Built the public sector comparator and PPP financial model for a bulk water supply project.$$, $$Review led the ministry to restructure the payment mechanism before tender.$$, $$[{"url":"https://picsum.photos/seed/demo-edvania-kiala-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-edvania-kiala-portfolio-1-img1/900/600","caption":"Site visit to the water treatment plant"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('d6f7358b-bc0d-4814-ba2b-9f635bfda5f6', 'edbe8a19-f5df-5783-9eb3-271e5edb711d', $$Trade Facilitation Diagnostic, Port of Lobito Corridor$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2024, 2024, $$Research Analyst$$, $$Supported a diagnostic of border and port procedures along the Lobito corridor, including interviews with traders and logistics firms.$$, $$Diagnostic identified six procedural reforms now in the government's trade facilitation plan.$$, $$[{"url":"https://picsum.photos/seed/demo-edvania-kiala-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-edvania-kiala-portfolio-2-img1/900/600","caption":"Port of Lobito"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('97dd1624-5a1f-576b-9b17-2c826f37e5a3', 'edbe8a19-f5df-5783-9eb3-271e5edb711d', $$Customs Time-Release Study, Lobito Corridor$$, $$African Development Bank$$, (SELECT id FROM organizations WHERE name = $$African Development Bank$$), 2024, 2025, $$Trade Facilitation Analyst$$, $$Measured the time taken by each step of import and transit clearance at the Port of Lobito and the Luau border post, using customs records and shipper interviews, and identified the steps that could move online.$$, $$Average clearance time mapped at 9.5 days; three procedures digitised in the follow-up programme.$$, $$[{"url":"https://picsum.photos/seed/demo-edvania-kiala-customs-time-release-study-lobito-corrid-1/900/600","caption":"Interviews with clearing agents at Lobito port"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
