-- Lerato Mokoena
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('3e1299b7-fb84-4280-b01e-fd188ecb9935', '565532b7-ac77-5b48-a69b-ea3008f79ae3', $$Microsimulation of Grant Reform Options$$, $$National Treasury of South Africa$$, (SELECT id FROM organizations WHERE name = $$National Treasury of South Africa$$), 2022, 2023, $$Lead Analyst$$, $$Modelled cost and poverty impacts of five options for reforming child and caregiver grants.$$, $$Results presented to the budget committee and used in the medium-term expenditure framework.$$, $$[{"url":"https://picsum.photos/seed/demo-lerato-mokoena-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-lerato-mokoena-portfolio-1-img1/900/600","caption":"Microsimulation results briefing"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('8266ca35-e380-48fa-9281-6a2b0bb84c76', '565532b7-ac77-5b48-a69b-ea3008f79ae3', $$Disability Grant Assessment Review$$, $$UNICEF South Africa$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2019, 2020, $$Research Lead$$, $$Reviewed medical and functional assessment processes for disability grants, with statistical analysis of approval rates by province.$$, $$Recommendations informed a revised assessment protocol.$$, $$[{"url":"https://picsum.photos/seed/demo-lerato-mokoena-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-lerato-mokoena-portfolio-2-img1/900/600","caption":"Stakeholder workshop in Pretoria"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('1b2af34c-d311-5daa-935b-018ac9754487', '565532b7-ac77-5b48-a69b-ea3008f79ae3', $$Behavioural Nudges for Child Support Grant Take-Up, Eastern Cape$$, $$UNICEF$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2021, 2022, $$Principal Investigator$$, $$Designed and evaluated SMS and clinic-based reminders encouraging caregivers of newborns to apply for the Child Support Grant early, using a randomised design across 60 clinics.$$, $$Applications within three months of birth rose by 11 percentage points in clinics with reminders.$$, $$[{"url":"https://picsum.photos/seed/demo-lerato-mokoena-behavioural-nudges-for-child-support-gra-1/900/600","caption":"Clinic reminder poster"},{"url":"https://picsum.photos/seed/demo-lerato-mokoena-behavioural-nudges-for-child-support-gra-2/900/600","caption":"Results workshop with the social security agency"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
