INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('755eb37c-32cb-41d9-8763-408a86a1049c', 'da399b2c-2d36-5ca1-8aca-84c15740d4db', $$Reservoir Level Forecasting Tool, Gaborone Dam$$, $$Department of Water and Sanitation, Botswana$$, NULL, 2023, 2024, $$Data Scientist$$, $$Built a Python forecasting model and dashboard for reservoir levels using rainfall, inflow and abstraction data.$$, $$Operators use the dashboard for weekly allocation decisions.$$, $$[{"url":"https://picsum.photos/seed/demo-onalenna-kgosietsile-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-onalenna-kgosietsile-portfolio-1-img1/900/600","caption":"Reservoir dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('63959d6b-8253-4803-8aba-d623041853df', 'da399b2c-2d36-5ca1-8aca-84c15740d4db', $$Drought Exposure Mapping, Limpopo Basin$$, $$Limpopo Watercourse Commission$$, NULL, 2021, 2022, $$GIS Analyst$$, $$Mapped drought exposure of rural water points using remote sensing indices and GIS.$$, $$Maps used to prioritize borehole rehabilitation.$$, $$[{"url":"https://picsum.photos/seed/demo-onalenna-kgosietsile-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-onalenna-kgosietsile-portfolio-2-img1/900/600","caption":"Drought exposure map"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('5fc7ea2e-2dd7-58cc-850d-7330a7128062', 'da399b2c-2d36-5ca1-8aca-84c15740d4db', $$Groundwater Quality Dashboard, Kweneng District$$, $$UNICEF$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2024, 2024, $$Data Analyst$$, $$Cleaned five years of borehole water quality records, flagged nitrate and fluoride exceedances, and built a dashboard for district water officers showing which boreholes need treatment or closure.$$, $$14 boreholes flagged for treatment; dashboard adopted by two more districts.$$, $$[{"url":"https://picsum.photos/seed/demo-onalenna-kgosietsile-groundwater-quality-dashboard-kweneng-di-1/900/600","caption":"Dashboard demonstration for district officers"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
